INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '創意滿滿！達摩彩繪親子體驗班圓滿成功，大小朋友齊心畫出專屬祝福 ✨',
           'A full house of creativity: parent-and-child Daruma painting workshop paints a wish for everyone ✨',
           '创意满满！达摩彩绘亲子体验班圆满成功，大小朋友齐心画出专属祝福 ✨',
           '喺2025年8月10日，樂橋聯同志橋外國語言教育，為大家帶來咗一場充滿色彩與歡笑聲嘅 **「達摩彩繪體驗班」**！今次活動主打親子同樂，吸引咗好多爸爸媽媽帶埋精靈活潑嘅小朋友一齊嚟發揮創意，場面超級熱鬧溫馨！達摩不倒翁喺傳統文化中代表著堅持不懈同心願達成。喺專業導師嘅帶領下，6位大小朋友一齊開展咗一場藝術創作之旅。',
           'On 10 August 2025 LucaBridge teamed up with Zhiqiao Foreign Language Education to run a Daruma painting workshop full of colour and laughter. The session was built around parents and children doing something together, and it drew plenty of families with lively young children ready to be creative.',
           '喺2025年8月10日，乐桥联同志桥外国语言教育，为大家带来咗一场充满色彩与欢笑声嘅 **「达摩彩绘体验班」**！今次活动主打亲子同乐，吸引咗好多爸爸妈妈带埋精灵活泼嘅小朋友一齐嚟发挥创意，场面超级热闹温馨！达摩不倒翁喺传统文化中代表著坚持不懈同心愿达成。喺专业导师嘅带领下，6位大小朋友一齐开展咗一场艺术创作之旅。',
           '喺2025年8月10日，樂橋聯同志橋外國語言教育，為大家帶來咗一場充滿色彩與歡笑聲嘅 **「達摩彩繪體驗班」**！今次活動主打親子同樂，吸引咗好多爸爸媽媽帶埋精靈活潑嘅小朋友一齊嚟發揮創意，場面超級熱鬧溫馨！達摩不倒翁喺傳統文化中代表著堅持不懈同心願達成。喺專業導師嘅帶領下，6位大小朋友一齊開展咗一場藝術創作之旅。

現場嘅小朋友個個化身「小藝術家」，拿起畫筆、沾上繽紛嘅顏料，專注咁喺達摩公仔上勾勒出獨一無二嘅圖案；而爸爸媽媽就喺身邊貼心協助，一邊引導、一邊讚賞，現場滿滿都是互相討論同歡笑嘅聲音，親子間嘅默契與溫情瞬間拉滿！經過大半日嘅努力，一尊尊充滿個性、色彩斑斕嘅專屬達摩公仔陸續誕生！看到小朋友們興高采烈咁捧住自己嘅作品，同爸爸媽媽一齊影大合照，臉上露出滿足又自豪嘅笑容，那一刻嘅畫面真係無比治癒！

在這裡衷心感謝智橋外國語教育嘅全力支持同完美場地配合，亦要謝謝每一組前來參與、投入100%熱情嘅精靈家庭！因為有你哋嘅支持，等小朋友喺動手創作嘅同時，更學懂了堅持與祝福嘅意義。愛心與創意並行，樂橋不停步，繼續同大家一齊探索、一齊進步！❤✨',
           'On 10 August 2025 LucaBridge teamed up with Zhiqiao Foreign Language Education to run a Daruma painting workshop full of colour and laughter.

The session was built around parents and children doing something together, and it drew plenty of families with lively young children ready to be creative. In traditional culture the Daruma doll stands for perseverance and for wishes fulfilled. Under the guidance of a professional instructor, six participants of various ages set off on an afternoon of making.

The children turned into small artists, picking up brushes, loading them with colour and concentrating hard on giving their Daruma a design nobody else would have. Parents helped alongside them, guiding and praising in equal measure, and the room filled with discussion and laughter. After most of a day, one distinctive, brightly painted Daruma after another was finished. Watching the children hold up their work for a group photo with their parents, proud and pleased with themselves, was a genuine tonic.

Our sincere thanks to Zhiqiao Foreign Language Education for their full support and for a venue that worked perfectly, and to every family who came and threw themselves into it. Because of you, the children came away having made something and having learned a little about persistence and good wishes. ❤✨',
           '喺2025年8月10日，乐桥联同志桥外国语言教育，为大家带来咗一场充满色彩与欢笑声嘅 **「达摩彩绘体验班」**！今次活动主打亲子同乐，吸引咗好多爸爸妈妈带埋精灵活泼嘅小朋友一齐嚟发挥创意，场面超级热闹温馨！达摩不倒翁喺传统文化中代表著坚持不懈同心愿达成。喺专业导师嘅带领下，6位大小朋友一齐开展咗一场艺术创作之旅。

现场嘅小朋友个个化身「小艺术家」，拿起画笔、沾上缤纷嘅颜料，专注咁喺达摩公仔上勾勒出独一无二嘅图案；而爸爸妈妈就喺身边贴心协助，一边引导、一边赞赏，现场满满都是互相讨论同欢笑嘅声音，亲子间嘅默契与温情瞬间拉满！经过大半日嘅努力，一尊尊充满个性、色彩斑斓嘅专属达摩公仔陆续诞生！看到小朋友们兴高采烈咁捧住自己嘅作品，同爸爸妈妈一齐影大合照，脸上露出满足又自豪嘅笑容，那一刻嘅画面真系无比治愈！

在这里衷心感谢智桥外国语教育嘅全力支持同完美场地配合，亦要谢谢每一组前来参与、投入100%热情嘅精灵家庭！因为有你哋嘅支持，等小朋友喺动手创作嘅同时，更学懂了坚持与祝福嘅意义。爱心与创意并行，乐桥不停步，继续同大家一齐探索、一齐进步！❤✨'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
SELECT b.id, m.id, v.ord
FROM blog b
CROSS JOIN (VALUES
        ('529372775_122231171306160773_1712744211652095344_n.jpg', 0),
        ('529701772_122231171288160773_6163495184588305346_n.jpg', 1)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2025-08-10-2'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2025-08-17  (2025-08-17)  PUBLISHED  [elderly]  一剎那的感動！走入八鄉恩和安老院，暖心福袋擦亮長者淚光與笑容 👵 Tears o
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
