                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-09-04-2',
           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '543418477_122235083786160773_8959391931717315875_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           1,
           'NONE',
           'PUBLISHED',
