INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '愛心響徹古洞！樂橋聯同香港紮作業聯會大出動，星級義工葉凱茵、顏仟汶、張柏文齊心送暖，特別鳴謝嘉頓公司與熱心人士贊助 🌟🍞',
           'Kwu Tung turns out: LucaBridge joins the Hong Kong Paper Crafting Association, with celebrity volunteers Yip Hoi-yan, Yan Chin-man and Cheung Pak-man, and thanks to The Garden Company and our donors 🌟🍞',
           '爱心响彻古洞！乐桥联同香港扎作业联会大出动，星级义工叶凯茵、颜仟汶、张柏文齐心送暖，特别鸣谢嘉顿公司与热心人士赞助 🌟🍞',
           '喺2025年9月13日，樂橋義工大隊聯同香港紮作業聯會，浩浩蕩蕩進擊古洞，展開了一場陣容超級鼎盛、人情味爆棚嘅福袋大派送送暖行動！今次活動可以話係結合咗各界嘅大愛力量！首先要特別鳴謝「嘉頓公司」慷慨贊助大批新鮮美味嘅麵包，以及熱心人士大力贊助嘅香脆餅乾，等我哋嘅福袋分量十足、滿載溫飽與祝福！更加令古洞街坊驚喜連連嘅，係我哋迎來了三位星光熠熠嘅星級義工——葉凱茵、顏仟汶同張柏文親身到場全力協助！',
           'On 13 September 2025 our volunteer team joined the Hong Kong Paper Crafting Association for a care package distribution in Kwu Tung, with a line-up and a level of warmth that were both hard to beat. This one brought together goodwill from several directions.',
           '喺2025年9月13日，乐桥义工大队联同香港扎作业联会，浩浩荡荡进击古洞，展开了一场阵容超级鼎盛、人情味爆棚嘅福袋大派送送暖行动！今次活动可以话系结合咗各界嘅大爱力量！首先要特别鸣谢「嘉顿公司」慷慨赞助大批新鲜美味嘅面包，以及热心人士大力赞助嘅香脆饼干，等我哋嘅福袋分量十足、满载温饱与祝福！更加令古洞街坊惊喜连连嘅，系我哋迎来了三位星光熠熠嘅星级义工——叶凯茵、颜仟汶同张柏文亲身到场全力协助！',
           '喺2025年9月13日，樂橋義工大隊聯同香港紮作業聯會，浩浩蕩蕩進擊古洞，展開了一場陣容超級鼎盛、人情味爆棚嘅福袋大派送送暖行動！今次活動可以話係結合咗各界嘅大愛力量！首先要特別鳴謝「嘉頓公司」慷慨贊助大批新鮮美味嘅麵包，以及熱心人士大力贊助嘅香脆餅乾，等我哋嘅福袋分量十足、滿載溫飽與祝福！更加令古洞街坊驚喜連連嘅，係我哋迎來了三位星光熠熠嘅星級義工——葉凱茵、顏仟汶同張柏文親身到場全力協助！

三位巨星一到場就化身最強送暖專員，同樂橋以及紮作業聯會嘅熱血義工隊伍默契配合，毫無架子。古洞嘅老友記同街坊見到一眾星級義工，個個展露出燦爛嘅笑容。凱茵、仟汶同柏文全程細心無比，親手將150袋裝滿嘉頓麵包、愛心餅乾同健康物資嘅沉甸甸福袋交到長者手中，仲一邊握手、一邊送上最真摯嘅問候。現場歡聲笑語此起彼落，溫馨嘅氛圍直接將古洞嘅氣溫加熱到最高點！

看著街坊們滿載而歸、臉上流露出滿足與安心嘅笑容，現場每一位揮汗如雨嘅義工夥伴都覺得所有辛苦都完全值回票價！喺度再次衷心感謝香港紮作業聯會嘅強強聯手、嘉頓公司與熱心人士嘅無私物資贊助，以及葉凱茵、顏仟汶、張柏文三位星級藝人嘅大愛付出！當然更少不了一班風雨同路、出汗出力嘅樂橋熱血義工家人！跨界齊行，善心無邊！樂橋不停步，帶著這份澎湃嘅正能量，繼續走向更多需要溫暖嘅角落！🔥🎒🌟',
           'On 13 September 2025 our volunteer team joined the Hong Kong Paper Crafting Association for a care package distribution in Kwu Tung, with a line-up and a level of warmth that were both hard to beat.

This one brought together goodwill from several directions. Our particular thanks to The Garden Company for generously donating a large quantity of fresh bread, and to the individual donors who supplied biscuits, which meant our packages were genuinely well filled. The other surprise for the residents of Kwu Tung was the arrival of three well-known volunteers — Yip Hoi-yan, Yan Chin-man and Cheung Pak-man — who came to help in person.

All three got straight to work alongside the LucaBridge and Paper Crafting Association volunteers, without a hint of ceremony. The elderly residents and neighbours of Kwu Tung lit up on seeing them. The three were attentive throughout, handing 150 heavy packages of Garden bread, donated biscuits and health items directly into people''s hands, shaking hands and offering warm greetings as they went. The laughter carried, and the mood in Kwu Tung went up several degrees.

Watching residents head home with full bags and satisfied, reassured faces, every volunteer there knew the effort had been worth it.

Our sincere thanks once more to the Hong Kong Paper Crafting Association for joining forces with us, to The Garden Company and our individual donors for their generosity, and to Yip Hoi-yan, Yan Chin-man and Cheung Pak-man for giving their time. And of course to the LucaBridge volunteers who turn out in all weather. 🔥🎒🌟',
           '喺2025年9月13日，乐桥义工大队联同香港扎作业联会，浩浩荡荡进击古洞，展开了一场阵容超级鼎盛、人情味爆棚嘅福袋大派送送暖行动！今次活动可以话系结合咗各界嘅大爱力量！首先要特别鸣谢「嘉顿公司」慷慨赞助大批新鲜美味嘅面包，以及热心人士大力赞助嘅香脆饼干，等我哋嘅福袋分量十足、满载温饱与祝福！更加令古洞街坊惊喜连连嘅，系我哋迎来了三位星光熠熠嘅星级义工——叶凯茵、颜仟汶同张柏文亲身到场全力协助！

三位巨星一到场就化身最强送暖专员，同乐桥以及扎作业联会嘅热血义工队伍默契配合，毫无架子。古洞嘅老友记同街坊见到一众星级义工，个个展露出灿烂嘅笑容。凯茵、仟汶同柏文全程细心无比，亲手将150袋装满嘉顿面包、爱心饼干同健康物资嘅沉甸甸福袋交到长者手中，仲一边握手、一边送上最真挚嘅问候。现场欢声笑语此起彼落，温馨嘅氛围直接将古洞嘅气温加热到最高点！

看著街坊们满载而归、脸上流露出满足与安心嘅笑容，现场每一位挥汗如雨嘅义工伙伴都觉得所有辛苦都完全值回票价！喺度再次衷心感谢香港扎作业联会嘅强强联手、嘉顿公司与热心人士嘅无私物资赞助，以及叶凯茵、颜仟汶、张柏文三位星级艺人嘅大爱付出！当然更少不了一班风雨同路、出汗出力嘅乐桥热血义工家人！跨界齐行，善心无边！乐桥不停步，带著这份澎湃嘅正能量，继续走向更多需要温暖嘅角落！🔥🎒🌟'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
