CROSS JOIN (VALUES
        ('546242037_17923767165130431_7116164444769896308_n.jpg', 0),
        ('547022077_122236570658160773_8128530840348708854_n.jpg', 1),
        ('547302330_122236247900160773_611517402897391757_n.jpg', 2),
        ('548293848_122236156130160773_1054214609856172712_n.jpg', 3),
        ('548301706_122236156088160773_2085291946732110334_n.jpg', 4),
        ('548313375_122236156184160773_6342854586343520167_n.jpg', 5),
        ('548415806_122236156226160773_2116410537453404487_n.jpg', 6)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
