    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2025-10-02'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2025-10-04  (2025-10-04)  PUBLISHED  [poverty]  愛心追月，溫暖延續！龍禧福袋月餅大派發，節日餘溫甜透老友記心房 🥮✨
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-10-04',
           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '558885260_122239207718160773_709522040944435910_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           1,
           'NONE',
           'PUBLISHED',
           '2025-10-04T00:00:00Z'::timestamptz,
           '2025-10-04T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2025-10-04')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '愛心追月，溫暖延續！龍禧福袋月餅大派發，節日餘溫甜透老友記心房 🥮✨',
           'The festival warmth continues: mooncakes and care packages at Lung Hei 🥮✨',
           '爱心追月，温暖延续！龙禧福袋月饼大派发，节日余温甜透老友记心房 🥮✨',
           '中秋過後，大愛依然熱辣辣！喺2025年10月4日，樂橋義工大隊嘅熱血腳步再次踏入充滿人情味嘅龍禧！準備踏入中秋，我哋堅持將節日嘅歡樂與關懷帶到最尾，當日特別備齊一袋袋沉甸甸、裝滿健康日常物資嘅暖心福袋，仲有應節嘅美味月餅，準備為一班街坊長者送上最窩心嘅週末「中秋」問候！當日現場一如既往咁人頭湧湧，老友記們一早就滿懷期待咁排隊支持。我哋著住整齊制服嘅熱血義工隊伍一到場就即刻火力全開，搬物資、排福袋、維持秩序，分工合作展現超強默契！',
           'Mid-Autumn has passed, but the warmth has not. On 4 October 2025 our volunteer team was back at Lung Hei. We were determined to carry the festival right to the end, so we came with well-filled care packages of everyday health items and festival mooncakes to go with them — a weekend Mid-Autumn greeting for the neighbourhood.',
           '中秋过后，大爱依然热辣辣！喺2025年10月4日，乐桥义工大队嘅热血脚步再次踏入充满人情味嘅龙禧！准备踏入中秋，我哋坚持将节日嘅欢乐与关怀带到最尾，当日特别备齐一袋袋沉甸甸、装满健康日常物资嘅暖心福袋，仲有应节嘅美味月饼，准备为一班街坊长者送上最窝心嘅周末「中秋」问候！当日现场一如既往咁人头涌涌，老友记们一早就满怀期待咁排队支持。我哋著住整齐制服嘅热血义工队伍一到场就即刻火力全开，搬物资、排福袋、维持秩序，分工合作展现超强默契！',
           '中秋過後，大愛依然熱辣辣！喺2025年10月4日，樂橋義工大隊嘅熱血腳步再次踏入充滿人情味嘅龍禧！準備踏入中秋，我哋堅持將節日嘅歡樂與關懷帶到最尾，當日特別備齊一袋袋沉甸甸、裝滿健康日常物資嘅暖心福袋，仲有應節嘅美味月餅，準備為一班街坊長者送上最窩心嘅週末「中秋」問候！當日現場一如既往咁人頭湧湧，老友記們一早就滿懷期待咁排隊支持。

我哋著住整齊制服嘅熱血義工隊伍一到場就即刻火力全開，搬物資、排福袋、維持秩序，分工合作展現超強默契！當大家將300袋福袋連同象徵圓滿嘅月餅親手遞到老友記手上，並用最響亮、最親切嘅聲音送上「祝你天天都好似中秋咁快樂、身體健康」嘅祝福時，街坊們接過禮物露出嘅舒心笑容，就是對我哋整個團隊最大嘅回報！看到一班老友記捧住月餅同福袋、開開心心咁話當初，那一刻，社區嘅人情味同義工們嘅熱血温度直接爆棚，全場都被幸福感徹底包圍！

在這裡要衷心感謝龍禧嘅全力支持與場地完美配合，更加要大讚當日不辭勞苦、揮汗如雨都依然笑容滿面嘅樂橋熱血義工家人！因為有你哋每一步嘅堅持，愛心先可以源源不絕咁傳遞落去。送暖不停步，大愛永相隨！樂橋會帶著呢份熱誠同正能量，走向更多有需要嘅地方！🔥🎒🥮🍱',
           'Mid-Autumn has passed, but the warmth has not. On 4 October 2025 our volunteer team was back at Lung Hei.

We were determined to carry the festival right to the end, so we came with well-filled care packages of everyday health items and festival mooncakes to go with them — a weekend Mid-Autumn greeting for the neighbourhood. The turnout was as strong as ever, with elderly residents queuing early in anticipation.

Our volunteers arrived in uniform and got straight to work — moving supplies, laying out packages, keeping the queue moving — with the kind of coordination that only comes from practice. As they handed over 300 care packages and the mooncakes that go with the season, with a warm "may every day be as good as Mid-Autumn, and stay well", the easy smiles that came back were the best return this team could ask for. Watching the elderly residents holding their mooncakes and packages, happily talking about times past, the whole place felt good to be in.

Our sincere thanks to Lung Hei for their full support and for hosting us so well, and full credit to every LucaBridge volunteer who worked hard all day and smiled through it.

Because you keep turning up, this keeps going. 🔥🎒🥮🍱',
           '中秋过后，大爱依然热辣辣！喺2025年10月4日，乐桥义工大队嘅热血脚步再次踏入充满人情味嘅龙禧！准备踏入中秋，我哋坚持将节日嘅欢乐与关怀带到最尾，当日特别备齐一袋袋沉甸甸、装满健康日常物资嘅暖心福袋，仲有应节嘅美味月饼，准备为一班街坊长者送上最窝心嘅周末「中秋」问候！当日现场一如既往咁人头涌涌，老友记们一早就满怀期待咁排队支持。

我哋著住整齐制服嘅热血义工队伍一到场就即刻火力全开，搬物资、排福袋、维持秩序，分工合作展现超强默契！当大家将300袋福袋连同象征圆满嘅月饼亲手递到老友记手上，并用最响亮、最亲切嘅声音送上「祝你天天都好似中秋咁快乐、身体健康」嘅祝福时，街坊们接过礼物露出嘅舒心笑容，就是对我哋整个团队最大嘅回报！看到一班老友记捧住月饼同福袋、开开心心咁话当初，那一刻，社区嘅人情味同义工们嘅热血温度直接爆棚，全场都被幸福感彻底包围！

在这里要衷心感谢龙禧嘅全力支持与场地完美配合，更加要大赞当日不辞劳苦、挥汗如雨都依然笑容满面嘅乐桥热血义工家人！因为有你哋每一步嘅坚持，爱心先可以源源不绝咁传递落去。送暖不停步，大爱永相随！乐桥会带著呢份热诚同正能量，走向更多有需要嘅地方！🔥🎒🥮🍱'
FROM ins;

