INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '熱血再燃，卡牌決戰！重臨紅磡電電屋引爆卡Game爭霸戰，特別鳴謝yumeno_card與palette2ptcg爆量獎品硬核贊助 🔥🏆✨',
           'Cards on the table again: the Din Din House league returns, with prizes generously backed by yumeno_card and palette2ptcg 🔥🏆✨',
           '热血再燃，卡牌决战！重临红磡电电屋引爆卡Game争霸战，特别鸣谢yumeno_card与palette2ptcg爆量奖品硬核赞助 🔥🏆✨',
           '雙線出擊，熱血無限放大！喺2025年10月12日呢個大豐收嘅日子，樂橋義工大隊不單止喺元朗送暖，我哋嘅潮流活力小分隊更再度重臨紅磡「電電屋」，舉辦了令全場玩家期待已久、激情澎湃嘅卡Game交流大賽！今次大賽之所以能夠規格升級、吸引大批頂尖玩家同大眾目光，一定要**特別鳴謝「yumeno_card」同埋「palette2ptcg」**嘅大愛與硬核贊助！',
           'Two fronts in one day. On 12 October 2025 our volunteers were not only in Yuen Long — a second group returned to Din Din House in Hung Hom for a card game tournament players had been waiting for. That this event stepped up in scale, drawing top players and a good deal of attention, is down to yumeno_card and palette2ptcg, who backed it with a generous haul of prizes.',
           '双线出击，热血无限放大！喺2025年10月12日呢个大丰收嘅日子，乐桥义工大队不单止喺元朗送暖，我哋嘅潮流活力小分队更再度重临红磡「电电屋」，举办了令全场玩家期待已久、激情澎湃嘅卡Game交流大赛！今次大赛之所以能够规格升级、吸引大批顶尖玩家同大众目光，一定要**特别鸣谢「yumeno_card」同埋「palette2ptcg」**嘅大爱与硬核赞助！',
           '雙線出擊，熱血無限放大！喺2025年10月12日呢個大豐收嘅日子，樂橋義工大隊不單止喺元朗送暖，我哋嘅潮流活力小分隊更再度重臨紅磡「電電屋」，舉辦了令全場玩家期待已久、激情澎湃嘅卡Game交流大賽！今次大賽之所以能夠規格升級、吸引大批頂尖玩家同大眾目光，一定要**特別鳴謝「yumeno_card」同埋「palette2ptcg」**嘅大愛與硬核贊助！

因為有你哋贊助出大批令所有卡牌玩家都流晒口水、極之珍貴嘅精美獎品同周邊，令今次比賽嘅含金量直接拉爆，全場選手嘅戰意瞬間被點燃到最高點！比賽當日，電電屋現場一早已經坐無虛席，高手雲集。我哋嘅熱血義工團隊著住整齊制服，熟練咁協助登記、維持秩序、炒熱氣氛。當裁判一聲令下，決鬥正式展開！34位選手們個個聚精會神，運籌帷幄、極速思考，一場場腦力與戰術嘅巔峰對決在桌面上激動上演！

每當有精采嘅神抽或者驚天逆轉，全場都會爆發出雷鳴般嘅歡呼聲同掌聲。而最令人激動嘅，當然係最後嘅頒獎時刻！當勝出者從我哋手中接過由yumeno_card同palette2ptcg贊助嘅夢幻獎品時，臉上展露出嘅自豪與興奮，以及台下參賽者雖敗猶榮嘅大合照笑容，直接將現場嘅青春熱血溫度拉到爆棚！卡牌承載夢想，比賽凝聚友誼！

今次活動成功透過卡Game呢個平台，將正能量、專注力同團隊精神成功傳遞給更多年輕人！在這裡再次衷心感謝電電屋提供場地配合、yumeno_card與palette2ptcg嘅鼎力贊助，以及當日所有全力以赴嘅參賽選手同出汗出力嘅樂橋熱血義工家人！多元跨界，樂橋不停步！無論是社區送暖還是潮流電競，只要有需要，我哋會繼續並肩前行，將正能量傳遍每一個角落！💪🔥🃏🎒',
           'Two fronts in one day. On 12 October 2025 our volunteers were not only in Yuen Long — a second group returned to Din Din House in Hung Hom for a card game tournament players had been waiting for.

That this event stepped up in scale, drawing top players and a good deal of attention, is down to yumeno_card and palette2ptcg, who backed it with a generous haul of prizes. The quality of what was on the table sent everyone''s competitive instincts straight up.

On the day, Din Din House was full before we started, with strong players everywhere. Our volunteers, in uniform, handled registration, kept things orderly and got the room going. When the judge gave the word, play began. All 34 competitors settled in, thinking fast and planning several moves ahead, and one tactical duel after another played out across the tables.

Every spectacular draw and every comeback brought the room down. The best of it, of course, was the prize-giving: watching the winners take the prizes sponsored by yumeno_card and palette2ptcg, proud and thrilled, and the group photo afterwards where everyone who had lost looked just as pleased to have been there.

Cards carry ambition, and a tournament builds friendships. Through this event, focus, teamwork and a good deal of positive energy reached a lot more young people.

Our sincere thanks again to Din Din House for the venue, to yumeno_card and palette2ptcg for their generous sponsorship, and to every competitor who gave it everything, along with the LucaBridge volunteers who made it run.

Whether it is a community distribution or a competitive card tournament, if there is a need, we will be there. 💪🔥🃏🎒',
           '双线出击，热血无限放大！喺2025年10月12日呢个大丰收嘅日子，乐桥义工大队不单止喺元朗送暖，我哋嘅潮流活力小分队更再度重临红磡「电电屋」，举办了令全场玩家期待已久、激情澎湃嘅卡Game交流大赛！今次大赛之所以能够规格升级、吸引大批顶尖玩家同大众目光，一定要**特别鸣谢「yumeno_card」同埋「palette2ptcg」**嘅大爱与硬核赞助！

因为有你哋赞助出大批令所有卡牌玩家都流晒口水、极之珍贵嘅精美奖品同周边，令今次比赛嘅含金量直接拉爆，全场选手嘅战意瞬间被点燃到最高点！比赛当日，电电屋现场一早已经坐无虚席，高手云集。我哋嘅热血义工团队著住整齐制服，熟练咁协助登记、维持秩序、炒热气氛。当裁判一声令下，决斗正式展开！34位选手们个个聚精会神，运筹帷幄、极速思考，一场场脑力与战术嘅巅峰对决在桌面上激动上演！

每当有精采嘅神抽或者惊天逆转，全场都会爆发出雷鸣般嘅欢呼声同掌声。而最令人激动嘅，当然系最后嘅颁奖时刻！当胜出者从我哋手中接过由yumeno_card同palette2ptcg赞助嘅梦幻奖品时，脸上展露出嘅自豪与兴奋，以及台下参赛者虽败犹荣嘅大合照笑容，直接将现场嘅青春热血温度拉到爆棚！卡牌承载梦想，比赛凝聚友谊！

今次活动成功透过卡Game呢个平台，将正能量、专注力同团队精神成功传递给更多年轻人！在这里再次衷心感谢电电屋提供场地配合、yumeno_card与palette2ptcg嘅鼎力赞助，以及当日所有全力以赴嘅参赛选手同出汗出力嘅乐桥热血义工家人！多元跨界，乐桥不停步！无论是社区送暖还是潮流电竞，只要有需要，我哋会继续并肩前行，将正能量传遍每一个角落！💪🔥🃏🎒'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
SELECT b.id, m.id, v.ord
FROM blog b
CROSS JOIN (VALUES
        ('560472110_122240534606160773_7757268720086747044_n.jpg', 0),
        ('561776128_122240534648160773_8559881477410807893_n.jpg', 1)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2025-10-12-2'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2025-10-18  (2025-10-18)  PUBLISHED  [poverty]  攜手星級義工，樂橋進擊大埔富善邨派發400份福袋，定點上門送暖獨居長者 👵❤
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-10-18',
           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '564598378_122241141806160773_5517670581369862475_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           1,
           'NONE',
           'PUBLISHED',
           '2025-10-18T00:00:00Z'::timestamptz,
           '2025-10-18T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2025-10-18')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '攜手星級義工，樂橋進擊大埔富善邨派發400份福袋，定點上門送暖獨居長者 👵❤',
           '400 care packages for Fu Shin Estate, Tai Po — delivered door to door to elderly residents living alone, alongside our celebrity volunteers 👵❤',
           '携手星级义工，乐桥进击大埔富善邨派发400份福袋，定点上门送暖独居长者 👵❤',
           '於2025年10月18日，樂橋義工隊伍前往大埔富善邨，聯同聚善義工組舉辦了福袋派發活動，合共送出400份裝滿實用物資的愛心福袋。今次活動非常榮幸邀請到星級義工顏仟汶、曾文心、以及仙杜拉親臨現場助陣。有各位星級藝人的支持，現場氣氛非常溫馨融洽，一眾街坊和老友記都展現出開心的笑容。除了在定點攤位派發外，為了照顧行動不便或獨居的長者，團隊特別安排義工分隊，親自上門將其中30份福袋送到長者家中。',
           'On 18 October 2025 our volunteers went to Fu Shin Estate in Tai Po and, together with the Jui Sin Volunteer Group, ran a care package distribution — 400 packages of practical supplies in total. We were very glad to have celebrity volunteers Yan Chin-man, Tsang Man-sum and Sandra with us on the day.',
           '于2025年10月18日，乐桥义工队伍前往大埔富善邨，联同聚善义工组举办了福袋派发活动，合共送出400份装满实用物资的爱心福袋。今次活动非常荣幸邀请到星级义工颜仟汶、曾文心、以及仙杜拉亲临现场助阵。有各位星级艺人的支持，现场气氛非常温馨融洽，一众街坊和老友记都展现出开心的笑容。除了在定点摊位派发外，为了照顾行动不便或独居的长者，团队特别安排义工分队，亲自上门将其中30份福袋送到长者家中。',
           '於2025年10月18日，樂橋義工隊伍前往大埔富善邨，聯同聚善義工組舉辦了福袋派發活動，合共送出400份裝滿實用物資的愛心福袋。今次活動非常榮幸邀請到星級義工顏仟汶、曾文心、以及仙杜拉親臨現場助陣。有各位星級藝人的支持，現場氣氛非常溫馨融洽，一眾街坊和老友記都展現出開心的笑容。除了在定點攤位派發外，為了照顧行動不便或獨居的長者，團隊特別安排義工分隊，親自上門將其中30份福袋送到長者家中。

在送上物資的同時，亦詳細詢問了他們的日常起居與身體狀況，落手落腳將關懷與溫暖直接送進家門。感謝聚善義工組的緊密協作，以及三位星級義工的愛心同行。樂橋未來會繼續深耕社區，用行動實踐「以生命影響生命」的精神！🌱✨',
           'On 18 October 2025 our volunteers went to Fu Shin Estate in Tai Po and, together with the Jui Sin Volunteer Group, ran a care package distribution — 400 packages of practical supplies in total.

We were very glad to have celebrity volunteers Yan Chin-man, Tsang Man-sum and Sandra with us on the day. With their support the mood was warm and easy, and the residents and elderly neighbours who came were visibly pleased.

As well as the distribution point itself, we made separate arrangements for elderly residents with limited mobility and those living alone: a team of volunteers took 30 of the packages to people''s homes and delivered them in person.

Along with the supplies, the volunteers asked in detail about how people were managing day to day and how their health was, bringing the care right to the door.

Our thanks to the Jui Sin Volunteer Group for working so closely with us, and to our three celebrity volunteers for giving their time. LucaBridge will keep working in this community, and keep putting into practice the idea that one life can reach another. 🌱✨',
           '于2025年10月18日，乐桥义工队伍前往大埔富善邨，联同聚善义工组举办了福袋派发活动，合共送出400份装满实用物资的爱心福袋。今次活动非常荣幸邀请到星级义工颜仟汶、曾文心、以及仙杜拉亲临现场助阵。有各位星级艺人的支持，现场气氛非常温馨融洽，一众街坊和老友记都展现出开心的笑容。除了在定点摊位派发外，为了照顾行动不便或独居的长者，团队特别安排义工分队，亲自上门将其中30份福袋送到长者家中。

在送上物资的同时，亦详细询问了他们的日常起居与身体状况，落手落脚将关怀与温暖直接送进家门。感谢聚善义工组的紧密协作，以及三位星级义工的爱心同行。乐桥未来会继续深耕社区，用行动实践「以生命影响生命」的精神！🌱✨'
FROM ins;

