-- 2025-10-25  (2025-10-25)  PUBLISHED  [poverty]  愛心承傳，萌爆元朗！重臨phone工場爆量派米送福袋，兩位最強「小義工」跨代合力
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-10-25',
           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '569815360_122242080962160773_1869366012634013645_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'NONE',
           'PUBLISHED',
           '2025-10-25T00:00:00Z'::timestamptz,
           '2025-10-25T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
