                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-11-22',
           (SELECT id FROM service WHERE code = 'campus' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '20251122.jpg' ORDER BY id LIMIT 1),
