INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '熱血不息，大愛續航！重臨元朗華苑粉麵爆量派福袋，風雨無阻守護街坊暖心週末 🍱✨',
           'Still going: back at Wah Yuen Noodles in Yuen Long with care packages, rain or shine 🍱✨',
           '热血不息，大爱续航！重临元朗华苑粉面爆量派福袋，风雨无阻守护街坊暖心周末 🍱✨',
           '善心不落空，天天都出擊！喺2025年11月27日，經歷過前線嘅突發支援挑戰後，樂橋義工大隊上下一心、幹勁依然爆燈，我哋嘅送暖列車再次駛回元朗老地方——華苑粉麵，開展新一輪嘅暖心福袋大派發活動！一到現場，大家著住整齊醒目嘅制服，二話不說即刻火力全開！搬運物資、清點福袋、拉起防線維持秩序，成個團隊展示出教科書級別嘅默契。一袋袋裝滿健康食品同日常必需品嘅沉甸甸福袋整齊排列，準備為前來嘅150位老友記同街坊送上最實質嘅支持與問候。',
           'Straight back out. On 27 November 2025, after the emergency work of the previous day, our volunteers returned to familiar ground — Wah Yuen Noodles in Yuen Long — for another round of care package distribution. The team arrived in uniform and got straight into it: shifting supplies, counting packages, setting up the queue.',
           '善心不落空，天天都出击！喺2025年11月27日，经历过前线嘅突发支援挑战后，乐桥义工大队上下一心、干劲依然爆灯，我哋嘅送暖列车再次驶回元朗老地方——华苑粉面，开展新一轮嘅暖心福袋大派发活动！一到现场，大家著住整齐醒目嘅制服，二话不说即刻火力全开！搬运物资、清点福袋、拉起防线维持秩序，成个团队展示出教科书级别嘅默契。一袋袋装满健康食品同日常必需品嘅沉甸甸福袋整齐排列，准备为前来嘅150位老友记同街坊送上最实质嘅支持与问候。',
           '善心不落空，天天都出擊！喺2025年11月27日，經歷過前線嘅突發支援挑戰後，樂橋義工大隊上下一心、幹勁依然爆燈，我哋嘅送暖列車再次駛回元朗老地方——華苑粉麵，開展新一輪嘅暖心福袋大派發活動！一到現場，大家著住整齊醒目嘅制服，二話不說即刻火力全開！搬運物資、清點福袋、拉起防線維持秩序，成個團隊展示出教科書級別嘅默契。

一袋袋裝滿健康食品同日常必需品嘅沉甸甸福袋整齊排列，準備為前來嘅150位老友記同街坊送上最實質嘅支持與問候。得知樂橋再次嚟到華苑，一班老街坊同老友記一早就滿懷期待咁排起長龍。我哋嘅熱血義工個個打足十二分精神，化身最強「福氣大使」，親手將福袋逐一交到街坊手上，並用最響亮、最親切嘅聲音送上叮囑：「長者們，最近天氣轉涼，攞袋福袋補補身，記住保重身體呀！」

看著老友記們接過福袋時，臉上展露出嘅驚喜與舒心笑容，聽著那一聲聲真摯嘅「多謝樂橋、多謝你哋又過嚟」，現場滿溢嘅人情味，直接將十一月尾嘅微涼秋意徹底融化！那一刻，大家就算搬到流晒大汗、手腳酸軟，內心都覺得熱血沸騰，成就感直接拉到最滿！在這裡要大聲感謝華苑粉麵一直以來嘅義氣相挺與場地完美配合，因為有你哋嘅強力後盾，樂橋先可以源源不絕咁將正能量直送社區；更要向當日無懼疲勞、持之以恆過嚟出汗出力嘅樂橋熱血義工家人致以最崇高嘅敬意！

有你哋同行，社區每個角落都充滿陽光！愛心不停步，樂橋永隨行！走向下一個需要溫暖嘅角落，下次再見！🔥🎒🎁✨',
           'Straight back out. On 27 November 2025, after the emergency work of the previous day, our volunteers returned to familiar ground — Wah Yuen Noodles in Yuen Long — for another round of care package distribution.

The team arrived in uniform and got straight into it: shifting supplies, counting packages, setting up the queue. Well-filled packages of food and everyday essentials were laid out in rows, ready for the 150 residents due that day.

Word that LucaBridge was back at Wah Yuen brought the regulars out early, and a queue formed well before we began. Our volunteers were on good form, handing over packages one by one with a warm word each time: "It''s turning cold — take this and look after yourself."

Watching the surprise and relief on people''s faces as they took their packages, and hearing "thank you LucaBridge, thank you for coming back", took the chill out of a late November afternoon. Aching arms and all, the team left feeling it had been worth the day.

A loud thank you to Wah Yuen Noodles for standing by us as they always do and for hosting us so well — with backing like that, we can keep bringing something good into this community — and our deepest respect to the LucaBridge volunteers who turned out again despite a hard week.

With you alongside us, there is sunlight in every corner of this place. On to the next one. 🔥🎒🎁✨',
           '善心不落空，天天都出击！喺2025年11月27日，经历过前线嘅突发支援挑战后，乐桥义工大队上下一心、干劲依然爆灯，我哋嘅送暖列车再次驶回元朗老地方——华苑粉面，开展新一轮嘅暖心福袋大派发活动！一到现场，大家著住整齐醒目嘅制服，二话不说即刻火力全开！搬运物资、清点福袋、拉起防线维持秩序，成个团队展示出教科书级别嘅默契。

一袋袋装满健康食品同日常必需品嘅沉甸甸福袋整齐排列，准备为前来嘅150位老友记同街坊送上最实质嘅支持与问候。得知乐桥再次嚟到华苑，一班老街坊同老友记一早就满怀期待咁排起长龙。我哋嘅热血义工个个打足十二分精神，化身最强「福气大使」，亲手将福袋逐一交到街坊手上，并用最响亮、最亲切嘅声音送上叮嘱：「长者们，最近天气转凉，攞袋福袋补补身，记住保重身体呀！」

看著老友记们接过福袋时，脸上展露出嘅惊喜与舒心笑容，听著那一声声真挚嘅「多谢乐桥、多谢你哋又过嚟」，现场满溢嘅人情味，直接将十一月尾嘅微凉秋意彻底融化！那一刻，大家就算搬到流晒大汗、手脚酸软，内心都觉得热血沸腾，成就感直接拉到最满！在这里要大声感谢华苑粉面一直以来嘅义气相挺与场地完美配合，因为有你哋嘅强力后盾，乐桥先可以源源不绝咁将正能量直送社区；更要向当日无惧疲劳、持之以恒过嚟出汗出力嘅乐桥热血义工家人致以最崇高嘅敬意！

有你哋同行，社区每个角落都充满阳光！爱心不停步，乐桥永随行！走向下一个需要温暖嘅角落，下次再见！🔥🎒🎁✨'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
SELECT b.id, m.id, v.ord
FROM blog b
CROSS JOIN (VALUES
        ('20251127.jpg', 0)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2025-11-27'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2025-11-30  (2025-11-30)  PUBLISHED  [poverty]  人帥心善，大愛元朗！再度進擊phone工場爆量派福袋，全體義工街坊激讚：老闆真係
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-11-30',
           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '20251130.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'NONE',
           'PUBLISHED',
           '2025-11-30T00:00:00Z'::timestamptz,
           '2025-11-30T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2025-11-30')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '人帥心善，大愛元朗！再度進擊phone工場爆量派福袋，全體義工街坊激讚：老闆真係人又靚仔、心地又善良 📱😎✨',
           'Yuen Long turns out again: a second round of care packages at Phone Factory, and a proprietor everyone agrees is as kind as he is good-looking 📱😎✨',
           '人帅心善，大爱元朗！再度进击phone工场爆量派福袋，全体义工街坊激赞：老板真系人又靓仔、心地又善良 📱😎✨',
           '十一月完美收官，愛心熱潮再度席捲元朗！喺2025年11月30日，樂橋義工大隊嘅送暖戰車再次駛入老地方**「phone工場」**，展開新一輪嘅150份暖心福袋大派發！而今日除了滿滿嘅物資之外，全場最亮眼嘅焦點，絕對係我哋不遺餘力、出錢出力嘅大好人老闆——人又靚仔、心地又善良，簡直係美貌與善心並重嘅最高化身！有咁正嘅老闆全力撐腰兼且提供完美場地，我哋一班著住醒目制服嘅熱血義工一到場就直落開足馬力！',
           'A good end to November, and Yuen Long got another round of it. On 30 November 2025 our volunteers were back at Phone Factory for a distribution of 150 care packages. Supplies aside, the person everyone had their eye on was the proprietor — a man who gives his money and his time without being asked, and who is, by universal agreement, as good-looking as he is kind.',
           '十一月完美收官，爱心热潮再度席卷元朗！喺2025年11月30日，乐桥义工大队嘅送暖战车再次驶入老地方**「phone工场」**，展开新一轮嘅150份暖心福袋大派发！而今日除了满满嘅物资之外，全场最亮眼嘅焦点，绝对系我哋不遗余力、出钱出力嘅大好人老板——人又靓仔、心地又善良，简直系美貌与善心并重嘅最高化身！有咁正嘅老板全力撑腰兼且提供完美场地，我哋一班著住醒目制服嘅热血义工一到场就直落开足马力！',
           '十一月完美收官，愛心熱潮再度席捲元朗！喺2025年11月30日，樂橋義工大隊嘅送暖戰車再次駛入老地方**「phone工場」**，展開新一輪嘅150份暖心福袋大派發！而今日除了滿滿嘅物資之外，全場最亮眼嘅焦點，絕對係我哋不遺餘力、出錢出力嘅大好人老闆——人又靚仔、心地又善良，簡直係美貌與善心並重嘅最高化身！

有咁正嘅老闆全力撐腰兼且提供完美場地，我哋一班著住醒目制服嘅熱血義工一到場就直落開足馬力！大家分工合作，極速將一袋袋裝滿健康食品、日常物資嘅沉甸甸福袋整齊排開。得知樂橋同phone工場再次聯手送暖，一班老友記同街坊一早就喺門口排起長龍，現場氣氛熱鬧到直接融化了十一月尾嘅微涼秋意！「長者們，入秋喇，記住注意保暖，攞袋福袋補補身呀！」

義工們一聲聲響亮、親切嘅問候在現場此起彼落。當大家將一份份充滿溫度嘅福袋交到老友記手中，看到長者們臉上展露出嘅舒心笑容，拉住我哋嘅手讚不絕口，那一刻，現場滿溢嘅人情味同幸福感直接衝破天際！全場義工就算搬到流晒大汗、手腳酸軟，內心都覺得熱血沸騰、超級值得！喺呢度，樂橋全體義工同元朗街坊要再次大聲向phone工場老闆致以最崇高、最熱烈嘅謝意！

多謝你每次都咁義氣相挺，用行動證明咩叫「人美心更美」（仲要咁靚仔！），你嘅大愛支持，就是樂橋源源不絕前行嘅最強後盾！同時亦要大讚當日全情投入、出汗出力嘅樂橋熱血義工家人！善心匯聚，靚人靚事！十一月雖然過去，但樂橋嘅送暖步伐絕不停歇。讓呢份澎湃嘅正能量，邁向更精彩嘅十二月，我們下一站見！🔥🎒🎁📱',
           'A good end to November, and Yuen Long got another round of it. On 30 November 2025 our volunteers were back at Phone Factory for a distribution of 150 care packages.

Supplies aside, the person everyone had their eye on was the proprietor — a man who gives his money and his time without being asked, and who is, by universal agreement, as good-looking as he is kind.

With backing like that and a perfect venue laid on, our volunteers arrived in uniform and got straight into it, laying out well-filled packages of food and everyday essentials at speed. Word that LucaBridge and Phone Factory were teaming up again brought a queue to the door early, and the mood took the chill straight out of a late-November afternoon.

"Autumn''s here — keep warm, and take a package to build yourself up." The greetings carried across the whole place. As package after package went into people''s hands, and the elderly residents took ours and praised us without pause, the warmth in that room went right through the roof. Aching arms, thoroughly sweaty, and every volunteer flying.

From all of us and from the residents of Yuen Long, our loudest thanks to the proprietor of Phone Factory. Thank you for standing by us every time, and for proving what it looks like when someone''s character matches their face (and what a face). Your support is the backing that keeps us moving. Full credit too to every LucaBridge volunteer who gave their all on the day.

November is done, but we are not. On to December. 🔥🎒🎁📱',
           '十一月完美收官，爱心热潮再度席卷元朗！喺2025年11月30日，乐桥义工大队嘅送暖战车再次驶入老地方**「phone工场」**，展开新一轮嘅150份暖心福袋大派发！而今日除了满满嘅物资之外，全场最亮眼嘅焦点，绝对系我哋不遗余力、出钱出力嘅大好人老板——人又靓仔、心地又善良，简直系美貌与善心并重嘅最高化身！

有咁正嘅老板全力撑腰兼且提供完美场地，我哋一班著住醒目制服嘅热血义工一到场就直落开足马力！大家分工合作，极速将一袋袋装满健康食品、日常物资嘅沉甸甸福袋整齐排开。得知乐桥同phone工场再次联手送暖，一班老友记同街坊一早就喺门口排起长龙，现场气氛热闹到直接融化了十一月尾嘅微凉秋意！「长者们，入秋喇，记住注意保暖，攞袋福袋补补身呀！」

义工们一声声响亮、亲切嘅问候在现场此起彼落。当大家将一份份充满温度嘅福袋交到老友记手中，看到长者们脸上展露出嘅舒心笑容，拉住我哋嘅手赞不绝口，那一刻，现场满溢嘅人情味同幸福感直接冲破天际！全场义工就算搬到流晒大汗、手脚酸软，内心都觉得热血沸腾、超级值得！喺呢度，乐桥全体义工同元朗街坊要再次大声向phone工场老板致以最崇高、最热烈嘅谢意！

多谢你每次都咁义气相挺，用行动证明咩叫「人美心更美」（仲要咁靓仔！），你嘅大爱支持，就是乐桥源源不绝前行嘅最强后盾！同时亦要大赞当日全情投入、出汗出力嘅乐桥热血义工家人！善心汇聚，靓人靓事！十一月虽然过去，但乐桥嘅送暖步伐绝不停歇。让呢份澎湃嘅正能量，迈向更精彩嘅十二月，我们下一站见！🔥🎒🎁📱'
FROM ins;

