INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '守護蔚藍，熱血淨灘！樂橋義工大隊進擊黃金海岸，無懼海風爆量清理垃圾，用大愛還原超美海岸線 🧹🎒✨',
           'Clearing the Gold Coast: volunteers brave the sea wind for a shoreline worth looking at 🧹🎒✨',
           '守护蔚蓝，热血净滩！乐桥义工大队进击黄金海岸，无惧海风爆量清理垃圾，用大爱还原超美海岸线 🧹🎒✨',
           '愛護社區，更要守護大自然！喺2025年12月7日，樂橋義工大隊嘅熱血足跡由市區延伸到大自然，我哋召集了大批充滿活力嘅義工家人，浩浩蕩蕩進擊屯門黃金海岸，開展了一場既考驗體力、又極具意義嘅沙灘清潔環保行動！活動當日，雖然海風陣陣帶點微涼，但我哋著住整齊醒目制服嘅熱血義工隊伍一去到沙灘，內心嘅環保之火即刻熊熊燃燒！大家帶齊手套、垃圾袋同夾子，分工合作化身成最強嘅「海岸守護者」，全速向沙灘各個角落推進，火力全開展開地毯式搜索！',
           'Looking after a community means looking after the natural world too. On 7 December 2025 our volunteers headed out of the city to the Gold Coast in Tuen Mun for a beach clean-up that tested everyone. The sea wind had a bite to it, but the moment our volunteers reached the sand they were away.',
           '爱护社区，更要守护大自然！喺2025年12月7日，乐桥义工大队嘅热血足迹由市区延伸到大自然，我哋召集了大批充满活力嘅义工家人，浩浩荡荡进击屯门黄金海岸，开展了一场既考验体力、又极具意义嘅沙滩清洁环保行动！活动当日，虽然海风阵阵带点微凉，但我哋著住整齐醒目制服嘅热血义工队伍一去到沙滩，内心嘅环保之火即刻熊熊燃烧！大家带齐手套、垃圾袋同夹子，分工合作化身成最强嘅「海岸守护者」，全速向沙滩各个角落推进，火力全开展开地毯式搜索！',
           '愛護社區，更要守護大自然！喺2025年12月7日，樂橋義工大隊嘅熱血足跡由市區延伸到大自然，我哋召集了大批充滿活力嘅義工家人，浩浩蕩蕩進擊屯門黃金海岸，開展了一場既考驗體力、又極具意義嘅沙灘清潔環保行動！活動當日，雖然海風陣陣帶點微涼，但我哋著住整齊醒目制服嘅熱血義工隊伍一去到沙灘，內心嘅環保之火即刻熊熊燃燒！

大家帶齊手套、垃圾袋同夾子，分工合作化身成最強嘅「海岸守護者」，全速向沙灘各個角落推進，火力全開展開地毯式搜索！不論是隱藏喺沙堆中嘅微細煙頭、塑膠碎片，還是被海浪沖上岸嘅廢棄膠樽、鋁罐，通通逃不過我哋一班金精火眼嘅義工！大家唔怕污糟、唔怕辛苦，彎腰俯身、出汗出力，哪怕是石縫深處嘅垃圾都一樣夾到清清楚楚。

「大家加油！執多一件垃圾，海洋生物就少一份危險，守護黃金海岸一齊衝！」現場充滿了義工們互相打氣、響亮又充滿幹勁嘅歡笑聲。經過大半日嘅努力，當看著14袋沉甸甸、堆積如山嘅成果，再回頭望向那片變得乾淨、重現閃爍金光嘅超美沙灘，那一刻，大家就算搬到手軟、流晒大汗，內心嘅成就感同自豪感直接衝破天際！在這裡要向當日所有不辭勞苦、無懼海風、俯身出力嘅樂橋熱血義工家人致以最崇高嘅敬意！

多謝你哋用雙手同汗水，為環保行出最堅實嘅一步，用行動證明咩叫「美貌與善心並重」嘅守護者！大愛無界，綠色同行！樂橋送暖不停步，環保腳步亦絕不落空！🔥🌊🧹🎒',
           'Looking after a community means looking after the natural world too. On 7 December 2025 our volunteers headed out of the city to the Gold Coast in Tuen Mun for a beach clean-up that tested everyone.

The sea wind had a bite to it, but the moment our volunteers reached the sand they were away. Gloves, bags and pickers out, the team spread across the beach and worked it methodically. Cigarette ends and fragments of plastic buried in the sand, discarded bottles and aluminium cans washed in by the tide — none of it got past them. Nobody minded the dirt or the effort; they bent down, worked hard, and cleared even the litter wedged deep between the rocks.

"Keep going! Every piece you pick up is one less hazard for marine life." The encouragement, and the laughter, carried all morning.

After most of a day, looking at 14 heavy bags piled up and then back at a beach that had got its golden shine back, the aching arms stopped mattering entirely.

Our deepest respect to every LucaBridge volunteer who worked through the sea wind without complaint. Thank you for taking a solid step for the environment with your own hands.

Community work and environmental work — neither one stops. 🔥🌊🧹🎒',
           '爱护社区，更要守护大自然！喺2025年12月7日，乐桥义工大队嘅热血足迹由市区延伸到大自然，我哋召集了大批充满活力嘅义工家人，浩浩荡荡进击屯门黄金海岸，开展了一场既考验体力、又极具意义嘅沙滩清洁环保行动！活动当日，虽然海风阵阵带点微凉，但我哋著住整齐醒目制服嘅热血义工队伍一去到沙滩，内心嘅环保之火即刻熊熊燃烧！

大家带齐手套、垃圾袋同夹子，分工合作化身成最强嘅「海岸守护者」，全速向沙滩各个角落推进，火力全开展开地毯式搜索！不论是隐藏喺沙堆中嘅微细烟头、塑胶碎片，还是被海浪冲上岸嘅废弃胶樽、铝罐，通通逃不过我哋一班金精火眼嘅义工！大家唔怕污糟、唔怕辛苦，弯腰俯身、出汗出力，哪怕是石缝深处嘅垃圾都一样夹到清清楚楚。

「大家加油！执多一件垃圾，海洋生物就少一份危险，守护黄金海岸一齐冲！」现场充满了义工们互相打气、响亮又充满干劲嘅欢笑声。经过大半日嘅努力，当看著14袋沉甸甸、堆积如山嘅成果，再回头望向那片变得干净、重现闪烁金光嘅超美沙滩，那一刻，大家就算搬到手软、流晒大汗，内心嘅成就感同自豪感直接冲破天际！在这里要向当日所有不辞劳苦、无惧海风、俯身出力嘅乐桥热血义工家人致以最崇高嘅敬意！

多谢你哋用双手同汗水，为环保行出最坚实嘅一步，用行动证明咩叫「美貌与善心并重」嘅守护者！大爱无界，绿色同行！乐桥送暖不停步，环保脚步亦绝不落空！🔥🌊🧹🎒'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
SELECT b.id, m.id, v.ord
FROM blog b
CROSS JOIN (VALUES
        ('594056793_122247913688160773_4258005922079684940_n.jpg', 0)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2025-12-07'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2025-12-09  (2025-12-09)  PUBLISHED  [poverty]  風雨同行，大愛不落空！全速進擊啟福居中轉屋，爆量物資暖心直送大埔受災街坊，攜手共
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2025-12-09',
           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '594019318_122248094018160773_3692854033342663529_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'CAROUSEL',
           'PUBLISHED',
           '2025-12-09T00:00:00Z'::timestamptz,
           '2025-12-09T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2025-12-09')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '風雨同行，大愛不落空！全速進擊啟福居中轉屋，爆量物資暖心直送大埔受災街坊，攜手共渡難關 🏡💪✨',
           'Through the worst of it: supplies delivered to Tai Po fire victims now housed at Kai Fuk Court transit housing 🏡💪✨',
           '风雨同行，大爱不落空！全速进击启福居中转屋，爆量物资暖心直送大埔受灾街坊，携手共渡难关 🏡💪✨',
           '水火無情，人情味更濃！自從11月26日大埔宏福苑發生突發火災以來，樂橋義工大隊嘅心一直與受災街坊緊緊連在一起。喺2025年12月9日，得知部分受災街坊目前正暫住於啟福居中轉屋、急需物資補充，我哋上下一心、義不容辭，即刻開展了這場充滿溫暖與速度嘅物資定點送暖行動！對於樂橋嚟講，街坊有需要，我哋無論如何都要送到！',
           'Fire and water have no feeling, but people do. Since the fire at Wang Fuk Court in Tai Po on 26 November, our volunteers had stayed close to the residents affected by it. On 9 December 2025, hearing that some of them were now living at Kai Fuk Court transit housing and running short of supplies, we went straight there.',
           '水火无情，人情味更浓！自从11月26日大埔宏福苑发生突发火灾以来，乐桥义工大队嘅心一直与受灾街坊紧紧连在一起。喺2025年12月9日，得知部分受灾街坊目前正暂住于启福居中转屋、急需物资补充，我哋上下一心、义不容辞，即刻开展了这场充满温暖与速度嘅物资定点送暖行动！对于乐桥嚟讲，街坊有需要，我哋无论如何都要送到！',
           '水火無情，人情味更濃！自從11月26日大埔宏福苑發生突發火災以來，樂橋義工大隊嘅心一直與受災街坊緊緊連在一起。喺2025年12月9日，得知部分受災街坊目前正暫住於啟福居中轉屋、急需物資補充，我哋上下一心、義不容辭，即刻開展了這場充滿溫暖與速度嘅物資定點送暖行動！對於樂橋嚟講，街坊有需要，我哋無論如何都要送到！

當日，我哋著住整齊醒目制服嘅熱血義工隊伍備齊了洗衣機，毛巾，爐具，抵達啟福居中轉屋，實行用最頂級嘅誠意，為正處於過渡期嘅大埔災民注入滿滿嘅關懷與正能量！一到現場，義工們即刻火力全開，搬運、清點、分發，成個流程行雲流水。當我哋親手將呢批愛心物資遞到受災老友記同街坊手中，並用最響亮、最真摯嘅聲音送上問候：「大家放心，家園雖然要重建，但有我哋樂橋同全港善心單位一齊撐住你哋！加油，保重身體！」

那一刻，街坊們眼神裡流露出的安心、感動與信任，就是對我們整個團隊最大嘅回報！看到街坊們從火災時嘅徬徨，到今日接過物資時露出的舒心笑容，現場滿溢嘅人情味，直接將十二月嘅寒意徹底驅散！大家就算搬到流晒大汗、手腳酸軟，內心都被徹底治癒，成就感直接衝破天際！這就是同舟共濟嘅香港精神，這就是樂橋永不熄滅嘅熱血溫度！

在這裡要衷心感謝啟福居中轉屋相關單位嘅全力協助與場地配合，更要向當日無懼辛勞、默默付出嘅樂橋熱血義工家人致以最崇高嘅敬意！多謝你哋用汗水，為災民築起最溫暖嘅港灣。逆境同行，大愛無疆！樂橋不停步，重建路上我哋繼續並肩衝刺，將正能量傳遍每一個角落！🔥🎒🎁🏡',
           'Fire and water have no feeling, but people do. Since the fire at Wang Fuk Court in Tai Po on 26 November, our volunteers had stayed close to the residents affected by it. On 9 December 2025, hearing that some of them were now living at Kai Fuk Court transit housing and running short of supplies, we went straight there.

As far as LucaBridge is concerned, if a resident needs something, we find a way to get it to them.

Our volunteers arrived at Kai Fuk Court in uniform with washing machines, towels and cooking equipment, intending to give the people going through this transition the best we had. On arrival the team got straight to work — carrying, counting, distributing, all of it flowing. As we handed the supplies to residents and elderly people in person, we told them what we had come to say: "The home will be rebuilt, and until it is, LucaBridge and a great many kind people across Hong Kong are behind you. Look after yourselves."

The reassurance and trust in their faces at that moment was all the return this team needed. Watching people go from the fear of the fire itself to the ease on their faces as they took what we had brought, the warmth in that place cleared the December cold out entirely. However much lifting anyone had done, everybody left mended. That is what standing together looks like here, and it is what keeps us going.

Our sincere thanks to everyone at Kai Fuk Court transit housing for their full assistance and cooperation, and our deepest respect to the LucaBridge volunteers who worked through the day without a word.

Rebuilding will take a while, and we will be alongside people for it. 🔥🎒🎁🏡',
           '水火无情，人情味更浓！自从11月26日大埔宏福苑发生突发火灾以来，乐桥义工大队嘅心一直与受灾街坊紧紧连在一起。喺2025年12月9日，得知部分受灾街坊目前正暂住于启福居中转屋、急需物资补充，我哋上下一心、义不容辞，即刻开展了这场充满温暖与速度嘅物资定点送暖行动！对于乐桥嚟讲，街坊有需要，我哋无论如何都要送到！

当日，我哋著住整齐醒目制服嘅热血义工队伍备齐了洗衣机，毛巾，炉具，抵达启福居中转屋，实行用最顶级嘅诚意，为正处于过渡期嘅大埔灾民注入满满嘅关怀与正能量！一到现场，义工们即刻火力全开，搬运、清点、分发，成个流程行云流水。当我哋亲手将呢批爱心物资递到受灾老友记同街坊手中，并用最响亮、最真挚嘅声音送上问候：「大家放心，家园虽然要重建，但有我哋乐桥同全港善心单位一齐撑住你哋！加油，保重身体！」

那一刻，街坊们眼神里流露出的安心、感动与信任，就是对我们整个团队最大嘅回报！看到街坊们从火灾时嘅徬徨，到今日接过物资时露出的舒心笑容，现场满溢嘅人情味，直接将十二月嘅寒意彻底驱散！大家就算搬到流晒大汗、手脚酸软，内心都被彻底治愈，成就感直接冲破天际！这就是同舟共济嘅香港精神，这就是乐桥永不熄灭嘅热血温度！

在这里要衷心感谢启福居中转屋相关单位嘅全力协助与场地配合，更要向当日无惧辛劳、默默付出嘅乐桥热血义工家人致以最崇高嘅敬意！多谢你哋用汗水，为灾民筑起最温暖嘅港湾。逆境同行，大爱无疆！乐桥不停步，重建路上我哋继续并肩冲刺，将正能量传遍每一个角落！🔥🎒🎁🏡'
FROM ins;

