           NULL,
           2,
           'NONE',
           'PUBLISHED',
           '2025-12-10T00:00:00Z'::timestamptz,
           '2025-12-10T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
