INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '跨界聯名，福氣滿滿！樂橋 × Phone工場強勢突擊大派福袋，熱血義工總動員，齊齊大汗淋漓迎新歲 📱🎒🔥✨',
           'LucaBridge x Phone Factory: care packages handed out ahead of the new year, and a lot of sweat 📱🎒🔥✨',
           '跨界联名，福气满满！乐桥 × Phone工场强势突击大派福袋，热血义工总动员，齐齐大汗淋漓迎新岁 📱🎒🔥✨',
           '喺2026年1月25日，樂橋義工大隊嘅熱血幹勁再度爆燈！今次我哋嘅愛心物資戰車直接駛到潮流與人情味兼備嘅**「Phone工場」**，強強聯手開展了這場別開生面、熱鬧非凡嘅福袋大派發行動，誓要在年前為各位街坊長者送上最暖心節日問候！一到現場，「Phone工場」內外一瞬間被一袋袋裝滿優質健康食品、實用物資、生活必需品嘅沉甸甸福袋堆滿。',
           'On 25 January 2026 our volunteers took the supply run to Phone Factory — a place with as much neighbourhood character as it has technology — for a care package distribution ahead of the new year. On arrival, Phone Factory inside and out filled up with well-stocked packages of good food, practical supplies and household essentials.',
           '喺2026年1月25日，乐桥义工大队嘅热血干劲再度爆灯！今次我哋嘅爱心物资战车直接驶到潮流与人情味兼备嘅**「Phone工场」**，强强联手开展了这场别开生面、热闹非凡嘅福袋大派发行动，誓要在年前为各位街坊长者送上最暖心节日问候！一到现场，「Phone工场」内外一瞬间被一袋袋装满优质健康食品、实用物资、生活必需品嘅沉甸甸福袋堆满。',
           '喺2026年1月25日，樂橋義工大隊嘅熱血幹勁再度爆燈！今次我哋嘅愛心物資戰車直接駛到潮流與人情味兼備嘅**「Phone工場」**，強強聯手開展了這場別開生面、熱鬧非凡嘅福袋大派發行動，誓要在年前為各位街坊長者送上最暖心節日問候！一到現場，「Phone工場」內外一瞬間被一袋袋裝滿優質健康食品、實用物資、生活必需品嘅沉甸甸福袋堆滿。

我哋嘅熱血義工隊伍與Phone工場嘅專業團隊展現出教科書級別嘅極致默契，分工合作、拉起防線、維持秩序，成個店面都洋溢著蓄勢待發嘅澎湃正能量！得知樂橋與Phone工場舉辦送暖，150位街坊同老友記一早就高高興興前來排隊支持，現場人頭湧湧，義工們個個化身成最強「福氣大使」，親手將精美福袋雙手遞到長者手中宏亮嘅叮囑在現場此起彼落。

看到老友記們接過福袋時，臉上展露出如春日陽光般燦爛、舒心嘅笑容，聽著那一聲聲拉著我哋手連連稱讚嘅「多謝你哋呀」，全場義工就算搬到汗流浹背、手腳酸軟，內心都被徹底治癒，成就感直接衝破天際！在這裡要大聲感謝Phone工場嘅全力支持、慷慨義舉與場地完美配合！因為有你哋嘅義氣相挺，潮流科技與社區慈善才可以完美融合，將愛心更精準、更舒適咁送到有需要嘅人手中！

同時亦要向當日無懼辛勞、在年前百忙之中依然出汗出力嘅樂橋熱血義工家人致以最崇高、最熱烈嘅敬意！社區齊心，其利斷金！我們下次再見！🔥🎒🎁📱⚡',
           'On 25 January 2026 our volunteers took the supply run to Phone Factory — a place with as much neighbourhood character as it has technology — for a care package distribution ahead of the new year.

On arrival, Phone Factory inside and out filled up with well-stocked packages of good food, practical supplies and household essentials.

Our volunteers and the Phone Factory team worked together with real coordination, dividing the work, setting up the queue and keeping order, and the whole shop filled with anticipation.

Word of the distribution brought 150 residents out early in good spirits, and the place was busy from the start. Our volunteers handed each package over with both hands and a warm word, and the greetings carried across the shop all day.

Watching the elderly residents take their packages with those bright, easy smiles, and hearing them hold our hands and say thank you, left every volunteer restored, however sweaty and sore.

A loud thank you to Phone Factory for their full support, their generosity and for hosting us so well. Because you back us the way you do, technology and community work fit together, and what we bring reaches people properly.

And our warmest respect to the LucaBridge volunteers who made time in a busy pre-new-year week to be there. See you next time. 🔥🎒🎁📱⚡',
           '喺2026年1月25日，乐桥义工大队嘅热血干劲再度爆灯！今次我哋嘅爱心物资战车直接驶到潮流与人情味兼备嘅**「Phone工场」**，强强联手开展了这场别开生面、热闹非凡嘅福袋大派发行动，誓要在年前为各位街坊长者送上最暖心节日问候！一到现场，「Phone工场」内外一瞬间被一袋袋装满优质健康食品、实用物资、生活必需品嘅沉甸甸福袋堆满。

我哋嘅热血义工队伍与Phone工场嘅专业团队展现出教科书级别嘅极致默契，分工合作、拉起防线、维持秩序，成个店面都洋溢著蓄势待发嘅澎湃正能量！得知乐桥与Phone工场举办送暖，150位街坊同老友记一早就高高兴兴前来排队支持，现场人头涌涌，义工们个个化身成最强「福气大使」，亲手将精美福袋双手递到长者手中宏亮嘅叮嘱在现场此起彼落。

看到老友记们接过福袋时，脸上展露出如春日阳光般灿烂、舒心嘅笑容，听著那一声声拉著我哋手连连称赞嘅「多谢你哋呀」，全场义工就算搬到汗流浃背、手脚酸软，内心都被彻底治愈，成就感直接冲破天际！在这里要大声感谢Phone工场嘅全力支持、慷慨义举与场地完美配合！因为有你哋嘅义气相挺，潮流科技与社区慈善才可以完美融合，将爱心更精准、更舒适咁送到有需要嘅人手中！

同时亦要向当日无惧辛劳、在年前百忙之中依然出汗出力嘅乐桥热血义工家人致以最崇高、最热烈嘅敬意！社区齐心，其利断金！我们下次再见！🔥🎒🎁📱⚡'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
SELECT b.id, m.id, v.ord
FROM blog b
CROSS JOIN (VALUES
        ('621656383_122254542158160773_6117836232222219040_n.jpg', 0)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2026-01-25'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2026-01-31  (2026-01-31)  PUBLISHED  [campus]  青春風暴，綠色出擊！樂橋聯同聖言中學、梁式芝書院學生突擊南丫島，直擊風車發電兼雷
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2026-01-31',
           (SELECT id FROM service WHERE code = 'campus' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '622374550_122255355194160773_2248831659482127377_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'CAROUSEL',
           'PUBLISHED',
           '2026-01-31T00:00:00Z'::timestamptz,
           '2026-01-31T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2026-01-31')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '青春風暴，綠色出擊！樂橋聯同聖言中學、梁式芝書院學生突擊南丫島，直擊風車發電兼雷霆清潔海岸線，用汗水點亮環保正能量 💨🎒🌱✨',
           'Students take on Lamma Island: LucaBridge joins Sing Yin Secondary School and Leung Shek Chee College to visit the wind turbine and clear the shoreline 💨🎒🌱✨',
           '青春风暴，绿色出击！乐桥联同圣言中学、梁式芝书院学生突击南丫岛，直击风车发电兼雷霆清洁海岸线，用汗水点亮环保正能量 💨🎒🌱✨',
           '大愛同行，守護藍天碧海！喺2026年1月31日，樂橋義工大隊上下一心、幹勁依然爆燈，我哋開展了一場極具教育意義與環保價值的「綠色生態保育大作戰」！今次我哋非常榮幸，能夠聯同聖言中學與梁式芝書院兩所傑出學校嘅精英學生，一同乘風破浪進擊南丫島，實行將科技探索與社區實踐完美結合，過一個最充實、最熱血嘅綠色冬日！第一站我哋前往「南丫風采發電站」，近距離直擊宏偉嘅巨大風車發電設施。',
           'On 31 January 2026 our volunteers ran a green conservation day built as much around learning as around work. We were very glad to be joined by students from two excellent schools — Sing Yin Secondary School and Leung Shek Chee College — for a trip to Lamma Island that put technology and community practice side by side.',
           '大爱同行，守护蓝天碧海！喺2026年1月31日，乐桥义工大队上下一心、干劲依然爆灯，我哋开展了一场极具教育意义与环保价值的「绿色生态保育大作战」！今次我哋非常荣幸，能够联同圣言中学与梁式芝书院两所杰出学校嘅精英学生，一同乘风破浪进击南丫岛，实行将科技探索与社区实践完美结合，过一个最充实、最热血嘅绿色冬日！第一站我哋前往「南丫风采发电站」，近距离直击宏伟嘅巨大风车发电设施。',
           '大愛同行，守護藍天碧海！喺2026年1月31日，樂橋義工大隊上下一心、幹勁依然爆燈，我哋開展了一場極具教育意義與環保價值的「綠色生態保育大作戰」！今次我哋非常榮幸，能夠聯同聖言中學與梁式芝書院兩所傑出學校嘅精英學生，一同乘風破浪進擊南丫島，實行將科技探索與社區實踐完美結合，過一個最充實、最熱血嘅綠色冬日！

第一站我哋前往「南丫風采發電站」，近距離直擊宏偉嘅巨大風車發電設施。喺老師介紹下，同學們個個聽得津津有味、眼神發光，深入了解再生能源對香港未來發展嘅重要性。呢一場教科書級別嘅實地考察，直接打破了課本嘅框架，將環保意識深深烙印喺每一位年輕人嘅心田！探索完綠色科技，真正考驗體力與默契嘅重頭戲正式引爆——雷霆清潔海岸線大行動！

同學們同樂橋義工迅速組成最強環保戰隊，帶齊手套、垃圾袋、鐵夾，火力全開空降南丫島海灘。面對石縫間、沙灘上被沖刷上岸嘅塑膠廢料同海洋垃圾，大家完全無懼烈日與海風，彎下腰、俯下身，不放過任何一個角落，分工合作將45袋垃圾一袋袋裝滿、搬走。看著大家搬到流晒大汗、手腳酸軟，但海灘喺我哋共同努力下，一瞬間回復了原本嘅潔淨、美麗與舒適，那一刻，全場青年學生同義工夥伴內心都湧現出無比嘅自豪與治癒感！

這不單止是一次義務工作，更是一場最深刻嘅跨代環境承傳，用年輕人嘅雙手，向大自然致以最崇高嘅敬意！在這裡要大聲感謝聖言中學與梁式芝書院嘅全體師生全力支持與全情投入，你哋展示出嘅青春活力同高度紀律，簡直係新世代青年嘅最強榜樣！同時亦要向當日帶隊、出汗出力、持之以恆實踐大愛嘅樂橋熱血義工家人致以最崇高、最熱烈嘅敬意！

多謝你哋用汗水點亮了南丫島嘅海岸線！山水相依，知行合一！讓我們繼續帶著呢份澎湃嘅正能量，迎向全新嘅一年！我們會為環保繼續衝刺，守護我哋嘅美麗家園！🔥🎒🌊🌱💨✨',
           'On 31 January 2026 our volunteers ran a green conservation day built as much around learning as around work.

We were very glad to be joined by students from two excellent schools — Sing Yin Secondary School and Leung Shek Chee College — for a trip to Lamma Island that put technology and community practice side by side.

Our first stop was the Lamma Winds power station, for a close look at the turbine itself. With their teachers explaining as we went, the students were absorbed, and came away with a proper understanding of why renewable energy matters to Hong Kong''s future. A field trip like that does something a textbook cannot.

Then came the part that tested everyone: clearing the shoreline. The students and our volunteers formed up quickly, kitted out with gloves, bags and pickers, and headed down to the beach. Faced with plastic waste and marine litter washed up across the sand and lodged between the rocks, nobody minded the sun or the wind. They bent down, worked every corner, and between them filled and carried away 45 bags.

Everyone was sweaty and sore by the end, but the beach had gone back to being clean and pleasant, and the pride among the students and volunteers was obvious.

This was more than volunteering; it was a proper handover between generations, with young people paying their respects to the natural world through their own effort.

A loud thank you to all the staff and students of Sing Yin Secondary School and Leung Shek Chee College for their full support and commitment — the energy and discipline you showed set a real standard. And our warmest respect to the LucaBridge volunteers who led the day.

Thank you for what you did for the Lamma Island shoreline. We''ll keep at it. 🔥🎒🌊🌱💨✨',
           '大爱同行，守护蓝天碧海！喺2026年1月31日，乐桥义工大队上下一心、干劲依然爆灯，我哋开展了一场极具教育意义与环保价值的「绿色生态保育大作战」！今次我哋非常荣幸，能够联同圣言中学与梁式芝书院两所杰出学校嘅精英学生，一同乘风破浪进击南丫岛，实行将科技探索与社区实践完美结合，过一个最充实、最热血嘅绿色冬日！

第一站我哋前往「南丫风采发电站」，近距离直击宏伟嘅巨大风车发电设施。喺老师介绍下，同学们个个听得津津有味、眼神发光，深入了解再生能源对香港未来发展嘅重要性。呢一场教科书级别嘅实地考察，直接打破了课本嘅框架，将环保意识深深烙印喺每一位年轻人嘅心田！探索完绿色科技，真正考验体力与默契嘅重头戏正式引爆——雷霆清洁海岸线大行动！

同学们同乐桥义工迅速组成最强环保战队，带齐手套、垃圾袋、铁夹，火力全开空降南丫岛海滩。面对石缝间、沙滩上被冲刷上岸嘅塑胶废料同海洋垃圾，大家完全无惧烈日与海风，弯下腰、俯下身，不放过任何一个角落，分工合作将45袋垃圾一袋袋装满、搬走。看著大家搬到流晒大汗、手脚酸软，但海滩喺我哋共同努力下，一瞬间回复了原本嘅洁净、美丽与舒适，那一刻，全场青年学生同义工伙伴内心都涌现出无比嘅自豪与治愈感！

这不单止是一次义务工作，更是一场最深刻嘅跨代环境承传，用年轻人嘅双手，向大自然致以最崇高嘅敬意！在这里要大声感谢圣言中学与梁式芝书院嘅全体师生全力支持与全情投入，你哋展示出嘅青春活力同高度纪律，简直系新世代青年嘅最强榜样！同时亦要向当日带队、出汗出力、持之以恒实践大爱嘅乐桥热血义工家人致以最崇高、最热烈嘅敬意！

多谢你哋用汗水点亮了南丫岛嘅海岸线！山水相依，知行合一！让我们继续带著呢份澎湃嘅正能量，迎向全新嘅一年！我们会为环保继续冲刺，守护我哋嘅美丽家园！🔥🎒🌊🌱💨✨'
FROM ins;

