           (SELECT id FROM service WHERE code = 'poverty' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '627928938_122256266726160773_2503348220023568417_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'CAROUSEL',
           'PUBLISHED',
           '2026-02-08T00:00:00Z'::timestamptz,
           '2026-02-08T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2026-02-08')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '筆走龍蛇，福傳萬家！樂橋新春熱血出擊大派手寫揮春，現場即席揮毫免費送福，用傳統墨香溫暖街坊心坎 ✍🎒🔥✨',
           'Ink and good wishes: hand-written fai chun brushed on the spot and given away for Lunar New Year ✍🎒🔥✨',
           '笔走龙蛇，福传万家！乐桥新春热血出击大派手写挥春，现场即席挥毫免费送福，用传统墨香温暖街坊心坎 ✍🎒🔥✨',
           '新春福氣，手寫最暖！大愛不卡關！喺2026年2月8日這個喜慶洋洋嘅正月日子裏，樂橋義工大隊嘅熱血幹勁依然爆燈！為了讓街坊老友記感受到最純粹、最有人情味嘅新春祝願，我哋上下一心，在社區定點開展了這場**「手寫揮春免費派發活動」**。我們要用一筆一劃、充滿生命力嘅毛筆字，為大家開創一個大吉大利、健康平安嘅全新一年！活動當日，一早已經到達現場，鋪好紅紙、備好筆墨、成個攤位一瞬間被紅噹噹、喜氣洋洋嘅節日氣氛彻底包圍。',
           'The warmest new year wishes are the hand-written kind. On 8 February 2026, in the middle of the Lunar New Year season, our volunteers set up in the community to give away hand-written fai chun, brushed on the spot. The team arrived early, laid out the red paper and set up the brushes and ink, and the stall filled with red and with the season.',
           '新春福气，手写最暖！大爱不卡关！喺2026年2月8日这个喜庆洋洋嘅正月日子里，乐桥义工大队嘅热血干劲依然爆灯！为了让街坊老友记感受到最纯粹、最有人情味嘅新春祝愿，我哋上下一心，在社区定点开展了这场**「手写挥春免费派发活动」**。我们要用一笔一划、充满生命力嘅毛笔字，为大家开创一个大吉大利、健康平安嘅全新一年！活动当日，一早已经到达现场，铺好红纸、备好笔墨、成个摊位一瞬间被红当当、喜气洋洋嘅节日气氛彻底包围。',
           '新春福氣，手寫最暖！大愛不卡關！喺2026年2月8日這個喜慶洋洋嘅正月日子裏，樂橋義工大隊嘅熱血幹勁依然爆燈！為了讓街坊老友記感受到最純粹、最有人情味嘅新春祝願，我哋上下一心，在社區定點開展了這場**「手寫揮春免費派發活動」**。我們要用一筆一劃、充滿生命力嘅毛筆字，為大家開創一個大吉大利、健康平安嘅全新一年！

活動當日，一早已經到達現場，鋪好紅紙、備好筆墨、成個攤位一瞬間被紅噹噹、喜氣洋洋嘅節日氣氛彻底包圍。當我哋嘅書法義工一落筆，筆走龍蛇、勁道十足，一幅幅「龍馬精神」、「出入平安」、「身體健康」嘅精美揮春陸續誕生印刷嘅揮春雖然精美，但手寫嘅揮春才最具有直擊心坎嘅溫度！我哋嘅熱血義工化身成最強「新春福氣大使」將散發著淡淡墨香嘅手寫揮春逐一親手交到長者同街坊手上。

大家唔單止送揮春，仲貼心咁向老街坊拜個正月中嘅熱鬧年，用最響亮、最親切嘅聲音叮囑：「公公婆婆、街坊們！新春快樂！攞幅手寫揮春返屋企貼，保佑全家全新一年身體健康、橫財就手、開開心心！」看著老友記們接過揮春、挑選到自己心水祝福時，臉上展露出如春日陽光般燦爛、滿足同驚喜嘅舒心笑容，聽著那一聲聲拉著我哋手連連稱讚嘅「你哋真係有心，多謝晒樂橋呀」，現場滿溢嘅濃厚人情味，這就是社區服務嘅最大價值——用最純粹嘅行動，傳承文化，溫暖人心！

在這裡要衷心感謝「寫到手軟」都堅持為街坊送上最好祝願嘅樂橋熱血義工書法家，多謝你哋用墨香，點亮了整個社區嘅新春回憶！善心匯聚，福氣綿延！讓我們繼續將呢份正能量，讓溫暖傳遞到更多角落，下一站再見！🔥🎒🧧✍✨',
           'The warmest new year wishes are the hand-written kind. On 8 February 2026, in the middle of the Lunar New Year season, our volunteers set up in the community to give away hand-written fai chun, brushed on the spot.

The team arrived early, laid out the red paper and set up the brushes and ink, and the stall filled with red and with the season.

Once our calligraphy volunteers started, the brushwork flowed, and one fai chun after another appeared — good health, safe travels, energy for the year ahead. Printed ones look fine, but a hand-written one carries something a printer cannot. Our volunteers handed each one over in person, still faintly smelling of ink.

They did more than hand them out, too — they wished everyone a proper new year while they were at it: "Happy new year! Take one home and put it up — health, good fortune and happiness to the whole family this year."

Watching the residents take their fai chun and pick out the wish they wanted, with those bright, surprised, pleased faces, and hearing them hold our hands and say "you''ve really thought about this — thank you", was community work doing exactly what it should: carrying a tradition forward and warming people up in the process.

Our sincere thanks to the LucaBridge calligraphy volunteers who wrote until their hands ached and kept going. Thank you for what that ink did for this neighbourhood''s new year. See you at the next one. 🔥🎒🧧✍✨',
           '新春福气，手写最暖！大爱不卡关！喺2026年2月8日这个喜庆洋洋嘅正月日子里，乐桥义工大队嘅热血干劲依然爆灯！为了让街坊老友记感受到最纯粹、最有人情味嘅新春祝愿，我哋上下一心，在社区定点开展了这场**「手写挥春免费派发活动」**。我们要用一笔一划、充满生命力嘅毛笔字，为大家开创一个大吉大利、健康平安嘅全新一年！

活动当日，一早已经到达现场，铺好红纸、备好笔墨、成个摊位一瞬间被红当当、喜气洋洋嘅节日气氛彻底包围。当我哋嘅书法义工一落笔，笔走龙蛇、劲道十足，一幅幅「龙马精神」、「出入平安」、「身体健康」嘅精美挥春陆续诞生印刷嘅挥春虽然精美，但手写嘅挥春才最具有直击心坎嘅温度！我哋嘅热血义工化身成最强「新春福气大使」将散发著淡淡墨香嘅手写挥春逐一亲手交到长者同街坊手上。

大家唔单止送挥春，仲贴心咁向老街坊拜个正月中嘅热闹年，用最响亮、最亲切嘅声音叮嘱：「公公婆婆、街坊们！新春快乐！攞幅手写挥春返屋企贴，保佑全家全新一年身体健康、横财就手、开开心心！」看著老友记们接过挥春、挑选到自己心水祝福时，脸上展露出如春日阳光般灿烂、满足同惊喜嘅舒心笑容，听著那一声声拉著我哋手连连称赞嘅「你哋真系有心，多谢晒乐桥呀」，现场满溢嘅浓厚人情味，这就是社区服务嘅最大价值——用最纯粹嘅行动，传承文化，温暖人心！

在这里要衷心感谢「写到手软」都坚持为街坊送上最好祝愿嘅乐桥热血义工书法家，多谢你哋用墨香，点亮了整个社区嘅新春回忆！善心汇聚，福气绵延！让我们继续将呢份正能量，让温暖传递到更多角落，下一站再见！🔥🎒🧧✍✨'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
SELECT b.id, m.id, v.ord
FROM blog b
CROSS JOIN (VALUES
        ('627928938_122256266726160773_2503348220023568417_n.jpg', 0),
        ('629651014_122256266756160773_8849358805208294784_n.jpg', 1)
    ) AS v(fn, ord)
JOIN media m ON m.file_name = v.fn
WHERE b.slug = '2026-02-08'
ON CONFLICT (blog_id, media_id) DO NOTHING;

-- 2026-02-13  (2026-02-13)  PUBLISHED  [campus]  超萌出擊，福氣爆棚！樂橋攜手英揚樂兒中英文幼稚園空降安心居，小萌娃新春送暖大玩遊
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2026-02-13',
           (SELECT id FROM service WHERE code = 'campus' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '20260213.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'NONE',
           'PUBLISHED',
           '2026-02-13T00:00:00Z'::timestamptz,
           '2026-02-13T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2026-02-13')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '超萌出擊，福氣爆棚！樂橋攜手英揚樂兒中英文幼稚園空降安心居，小萌娃新春送暖大玩遊戲，老友記笑逐顏開融化冬日 👶🧧❤✨',
           'The smallest visitors: LucaBridge and Ying Yeung Lok Yi Anglo-Chinese Kindergarten bring games and new year cheer to On Sum Kui 👶🧧❤✨',
           '超萌出击，福气爆棚！乐桥携手英扬乐儿中英文幼稚园空降安心居，小萌娃新春送暖大玩游戏，老友记笑逐颜开融化冬日 👶🧧❤✨',
           '童心傳愛，暖流破冰！喺2026年2月13日呢個春意盎然嘅喜慶正月裏，樂橋義工大隊上下一心、幹勁依然爆燈！為了讓安心居嘅公公婆婆感受到最純粹、最精靈嘅節日歡樂，我哋聯同英揚樂兒中英文幼稚園嘅一班「星級愛心小天使」突擊安老院，實行用跨代嘅愛心互動，為長者們送上揮春活動重頭戲隨即震撼開鑼！我哋嘅熱血義工與幼稚園老師默契配合，帶領小朋友同老友記一齊大玩新春互動遊戲、合唱賀年歌曲。',
           'Children make short work of any distance. On 13 February 2026, in the middle of a festive Lunar New Year, our volunteers teamed up with a group of small helpers from Ying Yeung Lok Yi Anglo-Chinese Kindergarten and headed to On Sum Kui. Our volunteers and the kindergarten teachers worked in step, leading the children and the residents through new year games and songs together.',
           '童心传爱，暖流破冰！喺2026年2月13日呢个春意盎然嘅喜庆正月里，乐桥义工大队上下一心、干劲依然爆灯！为了让安心居嘅公公婆婆感受到最纯粹、最精灵嘅节日欢乐，我哋联同英扬乐儿中英文幼稚园嘅一班「星级爱心小天使」突击安老院，实行用跨代嘅爱心互动，为长者们送上挥春活动重头戏随即震撼开锣！我哋嘅热血义工与幼稚园老师默契配合，带领小朋友同老友记一齐大玩新春互动游戏、合唱贺年歌曲。',
           '童心傳愛，暖流破冰！喺2026年2月13日呢個春意盎然嘅喜慶正月裏，樂橋義工大隊上下一心、幹勁依然爆燈！為了讓安心居嘅公公婆婆感受到最純粹、最精靈嘅節日歡樂，我哋聯同英揚樂兒中英文幼稚園嘅一班「星級愛心小天使」突擊安老院，實行用跨代嘅愛心互動，為長者們送上揮春活動重頭戲隨即震撼開鑼！我哋嘅熱血義工與幼稚園老師默契配合，帶領小朋友同老友記一齊大玩新春互動遊戲、合唱賀年歌曲。

小萌娃們用奶聲奶氣卻無比真摯嘅聲音大唱拜年歌，逗得長者們哈哈大笑，一邊送上最響亮嘅新春祝願：「祝公公婆婆身體健康！龍馬精神！」成個護老院一瞬間化成了最溫馨、最溫暖嘅幸福樂園，歡笑聲直接衝破天際！看著老友記們接過祝福時，臉上展露出如陽光般燦爛、舒心嘅滿足笑容，聽著那一聲聲拉著我哋手、摸著小朋友個頭連連稱讚嘅「今日真係好高興、好熱鬧，多謝晒樂橋同班小朋友呀」，那一刻，現場滿溢嘅濃厚人情味，直接將全場上下出汗出力嘅辛苦彻底治癒，成就感直接拉到最滿！

這不單止是一場探訪，更是一場最美麗、最無隔閡嘅社區文化承傳，用孩子們純粹嘅笑臉，向為社會貢獻一生嘅長者致以最崇高嘅敬意！在這裡要大聲感謝英揚樂兒中英文幼稚園全體校長、老師、同學及家長們嘅全力支持與全情投入，你哋展示出嘅愛心同活力，簡直係社區共融嘅最強榜樣！同時亦要向當日帶隊、出汗出力、持之以恆實踐大愛嘅每一位樂橋熱血義工家人致以最崇高、最熱烈嘅敬意！善心匯聚，大愛隨行！讓這份澎湃嘅正能量，全速前進，繼續衝刺！🔥🎒👶🧧✨',
           'Children make short work of any distance. On 13 February 2026, in the middle of a festive Lunar New Year, our volunteers teamed up with a group of small helpers from Ying Yeung Lok Yi Anglo-Chinese Kindergarten and headed to On Sum Kui.

Our volunteers and the kindergarten teachers worked in step, leading the children and the residents through new year games and songs together.

The children sang their new year songs in small, entirely sincere voices, which had the residents laughing out loud, and offered their good wishes at full volume: "Wishing you good health, grandad, grandma!" In no time the care home had turned into about the happiest room in the city.

Watching the residents take their good wishes with those bright, contented smiles, and hearing them hold our hands, pat the children''s heads and say "what a lovely, lively day — thank you LucaBridge and thank you to the children", made the effort disappear entirely.

This was more than a visit. It was a piece of cultural handover with no distance in it at all, in which children''s faces did the work of paying respect to people who have given a lifetime to this society.

A loud thank you to the principal, teachers, students and parents of Ying Yeung Lok Yi Anglo-Chinese Kindergarten for their full support and commitment — what you showed is about as good a model of an inclusive community as there is. And our warmest respect to every LucaBridge volunteer who led the day. 🔥🎒👶🧧✨',
           '童心传爱，暖流破冰！喺2026年2月13日呢个春意盎然嘅喜庆正月里，乐桥义工大队上下一心、干劲依然爆灯！为了让安心居嘅公公婆婆感受到最纯粹、最精灵嘅节日欢乐，我哋联同英扬乐儿中英文幼稚园嘅一班「星级爱心小天使」突击安老院，实行用跨代嘅爱心互动，为长者们送上挥春活动重头戏随即震撼开锣！我哋嘅热血义工与幼稚园老师默契配合，带领小朋友同老友记一齐大玩新春互动游戏、合唱贺年歌曲。

小萌娃们用奶声奶气却无比真挚嘅声音大唱拜年歌，逗得长者们哈哈大笑，一边送上最响亮嘅新春祝愿：「祝公公婆婆身体健康！龙马精神！」成个护老院一瞬间化成了最温馨、最温暖嘅幸福乐园，欢笑声直接冲破天际！看著老友记们接过祝福时，脸上展露出如阳光般灿烂、舒心嘅满足笑容，听著那一声声拉著我哋手、摸著小朋友个头连连称赞嘅「今日真系好高兴、好热闹，多谢晒乐桥同班小朋友呀」，那一刻，现场满溢嘅浓厚人情味，直接将全场上下出汗出力嘅辛苦彻底治愈，成就感直接拉到最满！

这不单止是一场探访，更是一场最美丽、最无隔阂嘅社区文化承传，用孩子们纯粹嘅笑脸，向为社会贡献一生嘅长者致以最崇高嘅敬意！在这里要大声感谢英扬乐儿中英文幼稚园全体校长、老师、同学及家长们嘅全力支持与全情投入，你哋展示出嘅爱心同活力，简直系社区共融嘅最强榜样！同时亦要向当日带队、出汗出力、持之以恒实践大爱嘅每一位乐桥热血义工家人致以最崇高、最热烈嘅敬意！善心汇聚，大爱随行！让这份澎湃嘅正能量，全速前进，继续冲刺！🔥🎒👶🧧✨'
FROM ins;

