INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '守護海岸，深井出擊！齊心協力清走六大袋海洋垃圾，還原美麗海景 💪',
           'Sham Tseng shoreline: six full bags of marine litter cleared, and the view back 💪',
           '守护海岸，深井出击！齐心协力清走六大袋海洋垃圾，还原美丽海景 💪',
           '喺2026年4月25日，樂橋嘅環保大隊再度熱血出動，今次我哋將減廢嘅腳步帶到去深井海岸！保護海洋生態絕對係一場需要持之以恆嘅硬仗。當日一班熱心義工放假都無偷懶，一早去到深井海灘，戴好手套、執條垃圾夾就即刻開工！沙灘上、石縫間佈滿咗好多由外海漂流過嚟嘅塑膠樽、即棄餐具同埋各式各樣嘅垃圾。大家不顧日曬、彎低腰，喺長長嘅海岸線上展開地毯式搜尋，不放過任何一個污染海洋嘅「元兇」。',
           'Our environmental team was out again, this time taking the clean-up to the Sham Tseng coast. Protecting marine life is a long campaign, not a one-off. A group of volunteers gave up their day off, arrived at Sham Tseng beach early, pulled on gloves, picked up their litter pickers and got straight to work.',
           '喺2026年4月25日，乐桥嘅环保大队再度热血出动，今次我哋将减废嘅脚步带到去深井海岸！保护海洋生态绝对系一场需要持之以恒嘅硬仗。当日一班热心义工放假都无偷懒，一早去到深井海滩，戴好手套、执条垃圾夹就即刻开工！沙滩上、石缝间布满咗好多由外海漂流过嚟嘅塑胶樽、即弃餐具同埋各式各样嘅垃圾。大家不顾日晒、弯低腰，喺长长嘅海岸线上展开地毯式搜寻，不放过任何一个污染海洋嘅「元凶」。',
           '喺2026年4月25日，樂橋嘅環保大隊再度熱血出動，今次我哋將減廢嘅腳步帶到去深井海岸！保護海洋生態絕對係一場需要持之以恆嘅硬仗。當日一班熱心義工放假都無偷懶，一早去到深井海灘，戴好手套、執條垃圾夾就即刻開工！沙灘上、石縫間佈滿咗好多由外海漂流過嚟嘅塑膠樽、即棄餐具同埋各式各樣嘅垃圾。大家不顧日曬、彎低腰，喺長長嘅海岸線上展開地毯式搜尋，不放過任何一個污染海洋嘅「元兇」。

經過大家一成朝嘅汗水同齊心協力，成果極之驚人——我哋足足清走咗六大袋沉甸甸嘅海洋垃圾！看着原本雜亂嘅海岸線喺大家努力之下，重新回復原本嘅潔淨與舒適，那一刻全場義工嘅成就感簡直爆棚！在這裡衷心感謝當日無懼辛勞、默默付出嘅每一位熱血環保戰士。因為有你哋嘅每一分汗水，我哋嘅海洋先可以維持美麗與健康。環境減廢，樂橋不停步，期待下一場繼續同你一齊守護藍天碧海！✨

編按：本文原稿所附相片經核實並非當日活動相片（實為另一活動相片誤置），現已移除，待尋回正確相片後補上。正文一字未改，全部照錄原稿。',
           'Our environmental team was out again, this time taking the clean-up to the Sham Tseng coast. Protecting marine life is a long campaign, not a one-off.

A group of volunteers gave up their day off, arrived at Sham Tseng beach early, pulled on gloves, picked up their litter pickers and got straight to work. The sand and the gaps between the rocks were covered in plastic bottles, disposable cutlery and waste of every kind, all drifted in from open water. Nobody minded the sun. They bent down and worked methodically along the length of the shoreline, leaving nothing behind.

A morning of sweat and good teamwork produced a striking result: six full bags of marine litter cleared. Watching a messy coastline return to being clean and pleasant, the satisfaction was considerable.

Our sincere thanks to every volunteer who worked hard and without fuss. It is your effort that keeps this sea healthy and worth looking at. We''ll see you at the next one. ✨',
           '喺2026年4月25日，乐桥嘅环保大队再度热血出动，今次我哋将减废嘅脚步带到去深井海岸！保护海洋生态绝对系一场需要持之以恒嘅硬仗。当日一班热心义工放假都无偷懒，一早去到深井海滩，戴好手套、执条垃圾夹就即刻开工！沙滩上、石缝间布满咗好多由外海漂流过嚟嘅塑胶樽、即弃餐具同埋各式各样嘅垃圾。大家不顾日晒、弯低腰，喺长长嘅海岸线上展开地毯式搜寻，不放过任何一个污染海洋嘅「元凶」。

经过大家一成朝嘅汗水同齐心协力，成果极之惊人——我哋足足清走咗六大袋沉甸甸嘅海洋垃圾！看着原本杂乱嘅海岸线喺大家努力之下，重新回复原本嘅洁净与舒适，那一刻全场义工嘅成就感简直爆棚！在这里衷心感谢当日无惧辛劳、默默付出嘅每一位热血环保战士。因为有你哋嘅每一分汗水，我哋嘅海洋先可以维持美丽与健康。环境减废，乐桥不停步，期待下一场继续同你一齐守护蓝天碧海！✨'
FROM ins;

-- 2026-05-11  (2026-05-11)  PUBLISHED  [volunteer]  走進議事廳，融入大灣區！樂橋受洪錦鉉立法會議員邀請參觀立法會，攜手張維樂主席共話
WITH ins AS (
    INSERT INTO blog (slug, service_id, cover_media_id, author_id, read_minutes,
                      gallery_layout, status, publish_at, published_at,
                      created_by, updated_by, created_at, updated_at)
    SELECT '2026-05-11',
           (SELECT id FROM service WHERE code = 'volunteer' LIMIT 1),
           (SELECT id FROM media WHERE file_name = '690760767_122268422126160773_2759622102427108730_n.jpg' ORDER BY id LIMIT 1),
           NULL,
           2,
           'GRID',
           'PUBLISHED',
           '2026-05-11T00:00:00Z'::timestamptz,
           '2026-05-11T00:00:00Z'::timestamptz,
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           (SELECT id FROM app_user ORDER BY id LIMIT 1),
           now(), now()
    WHERE NOT EXISTS (SELECT 1 FROM blog WHERE slug = '2026-05-11')
    RETURNING id
)
INSERT INTO blog_text (blog_id, tc_title, en_title, sc_title, tc_summary, en_summary, sc_summary, tc_body, en_body, sc_body)
SELECT id,
           '走進議事廳，融入大灣區！樂橋受洪錦鉉立法會議員邀請參觀立法會，攜手張維樂主席共話BTC培育計劃，全力加速中港青年融通交流 🦁🔥⚡✨',
           'Inside the chamber: LucaBridge visits the Legislative Council at the invitation of member Hung Kam-yuen, and discusses the BTC programme with chairman Cheung Wai-lok 🦁🔥⚡✨',
           '走进议事厅，融入大湾区！乐桥受洪锦铉立法会议员邀请参观立法会，携手张维乐主席共话BTC培育计划，全力加速中港青年融通交流 🦁🔥⚡✨',
           '開拓視野，強勢賦能，為青年未來點燃最強引擎！喺2026年5月11日，我哋非常榮幸獲得立法會洪錦鉉議員嘅親自邀請，帶領團隊走進香港政治與議事核心——立法會綜合大樓進行定點參觀與深度考察，實行讓大家近距離感受香港管治嘅莊嚴與魅力！當日，喺洪錦鉉議員嘅帶領與專業講解下，我哋深入了解了立法會嘅運作機制與歷史變遷，直接打破了課本與電視屏幕嘅框架，將宏觀嘅社會責任感與大局觀深深烙印喺每一位樂橋人嘅心田！',
           'On 11 May 2026 we were honoured to be invited by Legislative Council member Hung Kam-yuen to bring our team into the Legislative Council Complex for a visit and a closer look at how Hong Kong is governed.',
           '开拓视野，强势赋能，为青年未来点燃最强引擎！喺2026年5月11日，我哋非常荣幸获得立法会洪锦铉议员嘅亲自邀请，带领团队走进香港政治与议事核心——立法会综合大楼进行定点参观与深度考察，实行让大家近距离感受香港管治嘅庄严与魅力！当日，喺洪锦铉议员嘅带领与专业讲解下，我哋深入了解了立法会嘅运作机制与历史变迁，直接打破了课本与电视屏幕嘅框架，将宏观嘅社会责任感与大局观深深烙印喺每一位乐桥人嘅心田！',
           '開拓視野，強勢賦能，為青年未來點燃最強引擎！喺2026年5月11日，我哋非常榮幸獲得立法會洪錦鉉議員嘅親自邀請，帶領團隊走進香港政治與議事核心——立法會綜合大樓進行定點參觀與深度考察，實行讓大家近距離感受香港管治嘅莊嚴與魅力！當日，喺洪錦鉉議員嘅帶領與專業講解下，我哋深入了解了立法會嘅運作機制與歷史變遷，直接打破了課本與電視屏幕嘅框架，將宏觀嘅社會責任感與大局觀深深烙印喺每一位樂橋人嘅心田！

參觀過後，真正啟迪思維、決定未來方向嘅壓軸好戲正式震撼引爆——「羅湖深港青年發展契機交流活動」！大會更邀請到重量級嘉賓——香港音樂體育文化聯盟主席張維樂先生親臨現場作分享。張主席在會上高瞻遠矚，重磅介紹了即將全面啟動嘅**「粵港澳大灣區未來棟樑培育計劃BTC」**，並圍繞深港兩地青年嘅發展方向、機遇與挑戰展開了激情澎湃嘅定點交流！

這場交流會聚焦如何借助羅湖作為深港融合「橋頭堡」嘅獨特戰略優勢，為香港青年北上發展、創業、交流搭建一條極速高鐵。大家在會上各抒己見、火花四濺，探討如何透過文化、音樂與體育等多元軟實力，全方位增加中港青年嘅交流和融合，攜手培育出能夠肩負起時代重任嘅未來棟樑！聽完兩位重量級領袖嘅精闢獨到分享，現場每一位熱血義工同青年夥伴都聽得如癡如醉、眼神發光，內心湧現出無比嘅自豪與澎湃動力！

這不單止是一次高規格嘅參觀，更是一場深刻嘅思想洗禮與戰略對接。它讓我們看清了時代賦予年輕人嘅黃金機遇，明白到推動中港兩地「心聯通」、守護青年成長，樂橋絕對責無旁貸、必須衝鋒在前！在這裡要大聲感謝立法會洪錦鉉議員嘅熱情邀請與高度肯定，多謝你為社區青年打開這扇通往更高平台嘅大門；同時亦要衷心感謝香港音樂體育文化聯盟張維樂主席嘅無私分享與智慧賦能，你哋嘅大格局與大擔當，簡直係我哋前行路上最強嘅指路明燈！

更要向當日全情投入、持之以恆吸收正能量嘅樂橋熱血家人致以最崇高、最熱烈嘅敬意！立足香港，胸懷灣區！五月份嘅前進步伐以最強格局震撼開局！讓呢份大局觀與正能量，全速前進，為中港青年融合、為社區美好未來, 繼續衝刺！🔥🏛🦁🎒🌍⚡✨',
           'On 11 May 2026 we were honoured to be invited by Legislative Council member Hung Kam-yuen to bring our team into the Legislative Council Complex for a visit and a closer look at how Hong Kong is governed.

With Mr Hung guiding us and explaining as we went, we came away with a real understanding of how the Legislative Council works and how it has changed over time — the kind of understanding that a textbook or a television screen does not give you.

After the visit came the part that shaped the thinking: the Luohu Shenzhen-Hong Kong Youth Development exchange. The organisers had invited Mr Cheung Wai-lok, chairman of the Hong Kong Music, Sports and Culture Alliance, to speak. He gave a wide-ranging introduction to the Greater Bay Area Future Pillars Talent Cultivation Programme (BTC), which is about to launch in full, and led an energetic discussion on the opportunities and challenges facing young people in both Shenzhen and Hong Kong.

The session focused on how Luohu''s position as a bridgehead for Shenzhen-Hong Kong integration can open a fast route north for Hong Kong young people looking to work, start businesses or simply make connections. There was plenty of debate about how culture, music and sport can widen exchange between young people on both sides, and how to bring on the people who will carry the next stretch.

Listening to two speakers of that calibre, our volunteers and the young people with us came away genuinely fired up.

This was more than a high-level visit; it was a reset in how we think, and a useful alignment of direction. It made clear what opportunities are open to young people now, and that LucaBridge has a part to play in connecting the two places and supporting young people as they grow.

A loud thank you to Legislative Council member Hung Kam-yuen for the invitation and for his confidence in us — thank you for opening that door. Our sincere thanks too to chairman Cheung Wai-lok of the Hong Kong Music, Sports and Culture Alliance for sharing so generously; the scope of what you both do is a real signpost for us.

And our warmest respect to the LucaBridge family who came and took it all in. May is off to a strong start. 🔥🏛🦁🎒🌍⚡✨',
           '开拓视野，强势赋能，为青年未来点燃最强引擎！喺2026年5月11日，我哋非常荣幸获得立法会洪锦铉议员嘅亲自邀请，带领团队走进香港政治与议事核心——立法会综合大楼进行定点参观与深度考察，实行让大家近距离感受香港管治嘅庄严与魅力！当日，喺洪锦铉议员嘅带领与专业讲解下，我哋深入了解了立法会嘅运作机制与历史变迁，直接打破了课本与电视屏幕嘅框架，将宏观嘅社会责任感与大局观深深烙印喺每一位乐桥人嘅心田！

参观过后，真正启迪思维、决定未来方向嘅压轴好戏正式震撼引爆——「罗湖深港青年发展契机交流活动」！大会更邀请到重量级嘉宾——香港音乐体育文化联盟主席张维乐先生亲临现场作分享。张主席在会上高瞻远瞩，重磅介绍了即将全面启动嘅**「粤港澳大湾区未来栋梁培育计划BTC」**，并围绕深港两地青年嘅发展方向、机遇与挑战展开了激情澎湃嘅定点交流！

这场交流会聚焦如何借助罗湖作为深港融合「桥头堡」嘅独特战略优势，为香港青年北上发展、创业、交流搭建一条极速高铁。大家在会上各抒己见、火花四溅，探讨如何透过文化、音乐与体育等多元软实力，全方位增加中港青年嘅交流和融合，携手培育出能够肩负起时代重任嘅未来栋梁！听完两位重量级领袖嘅精辟独到分享，现场每一位热血义工同青年伙伴都听得如痴如醉、眼神发光，内心涌现出无比嘅自豪与澎湃动力！

这不单止是一次高规格嘅参观，更是一场深刻嘅思想洗礼与战略对接。它让我们看清了时代赋予年轻人嘅黄金机遇，明白到推动中港两地「心联通」、守护青年成长，乐桥绝对责无旁贷、必须冲锋在前！在这里要大声感谢立法会洪锦铉议员嘅热情邀请与高度肯定，多谢你为社区青年打开这扇通往更高平台嘅大门；同时亦要衷心感谢香港音乐体育文化联盟张维乐主席嘅无私分享与智慧赋能，你哋嘅大格局与大担当，简直系我哋前行路上最强嘅指路明灯！

更要向当日全情投入、持之以恒吸收正能量嘅乐桥热血家人致以最崇高、最热烈嘅敬意！立足香港，胸怀湾区！五月份嘅前进步伐以最强格局震撼开局！让呢份大局观与正能量，全速前进，为中港青年融合、为社区美好未来, 继续冲刺！🔥🏛🦁🎒🌍⚡✨'
FROM ins;

INSERT INTO blog_gallery (blog_id, media_id, sort_order)
