        ('690760767_122268422126160773_2759622102427108730_n.jpg', 0),
        ('693882697_122268422048160773_6550904110153026648_n.jpg', 1),
        ('694229120_122268422138160773_6275384969570065113_n.jpg', 2),
        ('698593984_122268422102160773_4993003381222603210_n.jpg', 3),
        ('698858969_122268422114160773_666425094953780706_n.jpg', 4),
        ('698876270_122268422090160773_5957875280887833831_n.jpg', 5),
        ('698888440_122268422036160773_5748092911832647389_n.jpg', 6)
    ) AS v(fn, ord)
